window.COMBAT_AI={"0":{"behaviors":[[0,"most_hp",4,"戳刺，+2{threat}"],[1,"furthest",6,"猛击"],[3,"closest",4,"戳刺 +1{damage}"]],"abilities":[{"name":"戳刺","die":"black","body":"1{damage}","grid":[".X.",".@.","..."]},{"name":"猛击","die":"red","body":"1{damage}","grid":[".X.","...",".@."]}],"weak":"+1{threat}","traits":["只是一次练习：若你被练习假人击败，抽取事件-12。"],"reward":"1{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件木制物品。","id":"0","name":"练习假人","faq":[{"question":"如果敌人攻击命中了我有护甲(仍有耐久）保护的部位，我是不是必须使用该护甲(来减少伤害），并放置一个磨损指示物？","answer":"是的！"},{"question":"“护甲点”图标表示什么？","answer":"这是生命点。一旦你击伤了一个敌人网格卡上的所有生命点(注意含护甲点与弱点)，就击败了该敌人！(参见:命中网格详解，第30页)"},{"question":"“暴击点”图标表示什么？","answer":"这是暴击点。当定向伤害的传播路径经过该图标时，会根据相应橙色箭头的指向造成附加伤害！"},{"question":"“弱点”图标表示什么？","answer":"这是弱点。击伤弱点将在伤害施加完之后再结算一个特定的效果。对本敌人而言，弱点效果为威胁+1。"},{"question":"“护甲点”图标表示什么？","answer":"这是护甲点。战斗开始时需在敌人的护甲点各放置一个护甲方块。当你对护甲点造成伤害时，移除该点的护甲方块(而不是放置损伤指示物)。一旦护甲方块被移除，该点将被视为普通生命点。"}],"original":"ai/FOE-0-26-1-back.webp"},"4":{"behaviors":[[0,"most_hp",2,"咬"],[1,"most_hp",5,"咬"],[3,"most",5,"狂咬"]],"abilities":[{"name":"咬","die":"yellow","body":"1{damage}","grid":[".X.",".@.","..."]},{"name":"狂咬","die":"yellow","body":"2{damage}","grid":[".X.","X@X",".X."]}],"weak":"+1{threat}","reward":"1{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件木制物品。","id":"4","name":"疯鼠","faq":[{"question":"狂咬的图示意思是能同时攻击多名流放者吗?","answer":"是的！"},{"question":"那攻击多名流放者时，我需要为每名流放者分别掷命中骰，还是仅掷一次?","answer":"仅掷一次，结果对所有目标生效。"},{"question":"每击败一只疯鼠，我是否都能获得卡牌底部标注的奖励（经验和战利品)？","answer":"不能！只有当你击败所有敌人，取得本场战斗胜利时(在其中的战利品步骤)，才能获得AI卡上的奖励，对于每张AI卡（即每种敌人），团队中每名流放者都获得相应数量的经验，但是战利品掷骰团队作为整体只进行一次。"},{"question":"“生命点”图标表示什么？","answer":"该图标代表“目标选择最多生命点的流放者”。若存在平手,敌人会选择移动距离最短即可攻击到的流放者;若仍平手，由玩家在其中选择。"},{"question":"“最多”图标表示什么？","answer":"该图标代表“目标选择最多”,即敌人会攻击尽可能多的流放者！若有多个位置可攻击到同样最多名的流放者，敌人会选择移动距离最短的位置；若仍平手，由玩家在其中选择。"}],"original":"ai/FOE-4-26-6-back.webp"},"5":{"behaviors":[[0,"most_hp",6,"啃咬"],[1,"most",5,"尾鞭"],[3,"most_hp",6,"啃咬 +1{damage}"],[5,"most",5,"尾鞭 +2{damage}"]],"abilities":[{"name":"啃咬","die":"black","body":"2{damage}","grid":[".X.","X.X","..."],"origin":[1,1.5]},{"name":"尾鞭","die":"blue","body":"1{damage}","grid":[".X.",".X.",".X.","...","..."],"origin":[1,3.5]}],"weak":"+1{threat}","reward":"1{xp}，以及键钥-1。","id":"5","name":"巨鼠","faq":[{"question":"尾鞭攻击从哪个方格或方向发起?","answer":"如图所示，从巨鼠长方形底座的两端之一发起(且与巨鼠朝向无关，虽然叫做尾鞭)。记住，敌人的网格位置也是可以随敌人模型旋转的（但网格位置不可以镜像翻转）。"}],"original":"ai/FOE-5-26-8-back.webp"},"11":{"behaviors":[],"abilities":[],"traits":["你试图将某人从冰封中解救出来！将此敌人视为占据事件-15所在的方格；本场战斗不能逃离。","抽取威胁卡时，按卡种对一个生命点造成伤害：所有敌人：3点；杂兵或首领：1点；其他卡：无。","若所有生命点受伤前，先移除了全部护甲方块：翻转事件-15，并将其放置在大型-2上。","若所有护甲移除前，全部生命点先受伤：人物-21转为B，随后翻转事件-15，并将其放置在大型-2上。"],"reward":"无。","id":"11","name":"冰封之中","faq":[{"question":"本场战斗中{threat}还有用吗?","answer":"没用了，只需关注抽出威胁卡的类型即可。实际上，本场战斗都不用记录变化。（不过你仍可以使用操控{threat}的能力，只不过没必要记录其数值变化）。"},{"question":"既然{threat}没用了，我还需要记录{combo}吗?","answer":"需要！请照常记录{combo}并按需使用。"},{"question":"本场战斗中，若抽出的威胁卡指示我再抽一张，也是要再抽一张吗?","answer":"是的。虽然本场战斗无需记录{threat}，但对于这种指示，还是要额外抽取威胁卡的。"},{"question":"我还能用“架盾冲锋”等技能变位目标吗?","answer":"不能。该目标无法被移动。但“架盾冲锋”仍会造成一点伤害。"},{"question":"游侠能标记此敌人吗?以及“冰封之中”属于敌人吗？","answer":"能，属于。“冰封之中”被视为敌人，所以游侠可对其使用标记技能。2/2敌人-11"}],"original":"ai/FOE-11-26-10-back.webp"},"13":{"behaviors":[[0,"most",5,"撕碎"],[2,"most",8,"撕碎，啸叫"]],"abilities":[{"name":"撕碎","die":"black","body":"5{damage}","grid":[".XX.","XXXX","....","...."],"origin":[1.5,2.5]},{"name":"啸叫","body":"所有流放者进行耐力20检定。失败：-3{hp}，并逃离4。"}],"weak":"攻击者 -2{hp}。","traits":["抑制愈合：所有治疗效果减半，治疗值向下取整。"],"reward":"事件-80。","id":"13","name":"鬼獠","faq":[{"question":"什么是“治疗效果”?","answer":"“治疗效果”指所有能让流放者获得{hp}的效果。而恢复{sp}或{mp}的效果，以及减少{hp}损失的效果，均不属于“治疗效果”，故不受此规则影响。"},{"question":"代表什么？","answer":"获得键钥-502。"},{"question":"此敌人是否同时属于首领和杂兵?","answer":"是的！当你抽出“首领”或“杂兵”威胁卡，此敌人都会激活。不过若你抽出“所有敌人”威胁卡，此敌人也仅激活一次。"},{"question":"如何正确结算这个弱点效果？","answer":"若你是弱点受到损伤的直接来源,你将损失{hp}。"},{"question":"逃离4是什么意思?","answer":"敌人以4向远离目标的方向移动。2/2敌人-13"}],"original":"ai/FOE-13-26-12-back.webp"},"16":{"behaviors":[[0,"closest",null,"逃离4，+2{threat}"],[1,"most",4,"挥砍"],[3,"most",6,"挥砍，盾击"]],"abilities":[{"name":"盾击","die":"black","body":"1{damage}。若可能，将目标推远1格；若不能推远，则+1{damage}。","grid":["...",".X.",".@."],"push":true,"pushArrows":true},{"name":"挥砍","die":"blue","body":"2{damage}","grid":[".X.","X@.","..."]}],"weak":"+1{threat}","reward":"1{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件木制物品。","id":"16","name":"蜥精强盗","faq":[{"question":"“盾击”会将目标推向哪个方向?","answer":"由玩家决定(即选一个箭头方向）。"},{"question":"对于0{threat}行为，是每只激活的蜥精强盗都会使增加吗？","answer":"是的!每只激活的蜥精强盗都会使{threat}+2。"},{"question":"逃离4是什么意思?","answer":"敌人以4向远离目标的方向移动。"}],"original":"ai/FOE-16-26-16-back.webp"},"18":{"behaviors":[[0,"furthest",5,"踢击，讥讽"],[1,"most",4,"挥斧，踢击"],[3,"most",4,"挥斧，讥讽，踢击"]],"abilities":[{"name":"讥讽","body":"+2{threat}。所有流放者进行感知10检定；失败：-1{sp}。"},{"name":"踢击","die":"yellow","body":"2{damage}。从目标处拿取1{kae}，放在这张卡上。","grid":["XXX",".@.","..."],"choice":true},{"name":"挥斧","die":"red","body":"2{damage}","grid":["XXX",".@.","..."]}],"weak":"持续：若两个弱点均已受伤，忽略踢击。","reward":"1{xp}、键钥-4、事件-14。","id":"18","name":"厄基·菲尔茨","faq":[{"question":"对于“讥讽”效果，是每名流放者单独结算检定吗？","answer":"是的！"},{"question":"若“讥讽”检定成功，则无事发生?","answer":"是的！该检定仅在失败时才会触发效果。"},{"question":"若我已没有剩余{sp}，再要失去时会发生什么？","answer":"无事发生。"},{"question":"“踢击”的位置网格中，虚线选框代表什么?","answer":"代表“踢击”仅从虚线选框方格中选择一名流放者作为目标(若有需要，由玩家选择)。(参见：位置网格，第21页）"},{"question":"弱点效果文本读起来感觉是对玩家有利的?","answer":"是的！有时击伤弱点对流放者是有利的。"},{"question":"若我逃离或被击败，能否从厄基那里取回被踢击拿走的？","answer":"不能，他不会还给你们的。若你逃离或被击败，需将本卡上的加伊放回供应堆。2/2敌人-18"}],"original":"ai/FOE-18-26-18-back.webp"},"22":{"behaviors":[[0,"closest",null,"逃离3，+2{threat}"],[1,"most",6,"奔袭"],[3,"most",8,"奔袭 +1{damage}"]],"abilities":[{"name":"奔袭","die":"yellow","body":"尽可能多地穿过流放者所在的方格，但不能在任何流放者所在的方格结束移动。对每名被穿过的流放者造成1{damage}，每回合至多一次。"}],"weak":"治疗1个非弱点生命点。","reward":"1{xp}；特殊：事件-19。","id":"22","name":"发狂野猪","faq":[{"question":"逃离3是什么意思?","answer":"敌人以3向远离目标的方向移动。"},{"question":"对于0行为，是每只激活的发狂野猪都会使增加吗？","answer":"是的！每只激活的发狂野猪都会使+2。"},{"question":"对于这个弱点效果，哪个生命点会被治疗?","answer":"由流放者决定。"},{"question":"敌人真的能穿过流放者移动吗?","answer":"通常情况下不能！但“奔袭”是使敌人能穿过流放者移动的特殊能力。"},{"question":"对于“奔袭”,若敌人的移动力仅足够部分穿过我，无法完全穿过我，会发生什么？","answer":"那就无法“奔袭”穿过你，会在与你相邻的位置就结束移动。"},{"question":"若敌人“奔袭”穿过所有流放者后仍有剩余移动力，会如何?","answer":"敌人会停止移动，结束此次奔袭。"},{"question":"若敌人仅能穿过部分流放者，而非所有流放者，剩余的移动力会如何使用？","answer":"敌人会向尚未穿过的最近流放者尽量移动。"}],"original":"ai/FOE-22-26-21-back.webp"},"24":{"behaviors":[[0,"most_hp",4,"顶撞，+2{threat}"],[1,"most",7,"奔袭"],[3,"most_hp",6,"顶撞 +2{damage}"]],"abilities":[{"name":"奔袭","die":"yellow","body":"尽可能多地穿过流放者所在的方格，但不能在任何流放者所在的方格结束移动。对每名被穿过的流放者造成2{damage}，每回合至多一次。"},{"name":"顶撞","die":"black","body":"3{damage}","grid":[".X.","...","..."],"origin":[1,1.5]}],"weak":"治疗2个非弱点生命点。","reward":"2{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件木制物品。","id":"24","name":"血牙野猪","faq":[{"question":"对于这个弱点效果，哪些生命点会被治疗?","answer":"由流放者决定。"},{"question":"若敌人“奔袭”穿过所有流放者后仍有剩余移动力，会如何?","answer":"敌人会停止移动，结束此次奔袭。"},{"question":"若敌人仅能穿过部分流放者，而非所有流放者，剩余的移动力会如何使用？","answer":"敌人会向尚未穿过的最近流放者尽量移动。"},{"question":"若战士在一次“奔袭”结算过程中使用“守护”技能，会发生什么？","answer":"这种情况下战士受到两次奔袭的伤害(守护目标本应受到的一次，外加战士自己被撞到的一次）。"},{"question":"若野猪“奔袭”穿过处于隐藏状态的游荡者，会发生什么？","answer":"游荡者会受到伤害，且失去隐藏状态(只有当野猪穿过了游荡者所在方格时才会这样)。"}],"original":"ai/FOE-24-26-23-back.webp"},"32":{"behaviors":[[0,"most",6,"吸收，+3{threat}"],[1,"most",5,"吸收，软泥猛胀"],[3,"most",8,"吸收，软泥猛胀 +1{damage}"]],"abilities":[{"name":"吸收","body":"感知16检定。失败：掷黑色与蓝色命中骰，并将命中的护甲放在这张卡上。","grid":[".XX.","X..X","X..X",".XX."],"origin":[1.5,1.5]},{"name":"软泥猛胀","die":"black","body":"X{damage}。X等于本卡护甲数量，最少为1。","grid":[".XX.","X..X","X..X",".XX."],"origin":[1.5,1.5]}],"weak":"+1{threat}","traits":["若你逃离或被击败，取回这张卡上的所有护甲。"],"reward":"2{xp}；特殊：事件-26。取回这张卡上的所有护甲。","id":"32","name":"橙浆怪","faq":[{"question":"“吸收”的效果不会造成伤害吗?","answer":"是的！“吸收”不会造成伤害。每名目标流放者分别进行感知检定，失败了就要分别投掷{marker}和命中骰，然后其被命中的护甲会立即放置在本卡上。"},{"question":"如果被吸收的护甲上有磨损指示物，在取回护甲时会如何处理？","answer":"磨损指示物情况仍然保持原样。"},{"question":"“软泥猛胀X”中的“X”代表什么?","answer":"X代表橙浆怪通过“吸收”放置在本卡上的护甲物品数量。若本卡上无护甲物品，则X=1。"},{"question":"若“吸收”效果命中了战士的盾防指示物，会发生什么？","answer":"橙浆怪会获取该盾防指示物对应的盾牌物品，以及命中部位上的护甲！"},{"question":"“吸收”效果与游荡者的警戒指示物如何互动？","answer":"警戒指示物会被移除,且游荡者失去隐藏状态。2/2敌人-32"}],"original":"ai/FOE-32-26-25-back.webp"},"35":{"behaviors":[[0,"most_hp",6,"切割"],[1,"most",4,"大颚"],[3,"most",5,"大颚 +2{damage}"]],"abilities":[{"name":"切割","die":"black","body":"1{damage}","grid":[".X.",".@.","..."]},{"name":"大颚","die":"blue","body":"1{damage}","grid":["XXX",".@.","..."]}],"weak":"+2{threat}","reward":"1{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件木制物品。","id":"35","name":"兵蚁","faq":[{"question":"对于事件-309，若“狂奔蚁”(那个逃窜的蚂蚁）是仅存的兵蚁，其执行行为时仍需支付{threat}吗？","answer":"是的。5/5敌人-35"}],"original":"ai/FOE-35-26-30-back.webp"},"38":{"behaviors":[[0,"most",4,"尖刺，+2{threat}"],[1,"most",5,"尖刺，逃离3"],[3,"most",6,"尖刺 +1{damage}（所有目标）"]],"abilities":[{"name":"尖刺","die":"yellow","body":"选择4{distance}内的流放者，造成2{damage}；与目标相邻的流放者受到1{damage}。","grid":[".X.","XXX",".X."],"origin":[1,1],"originKind":"area","attackType":"area"}],"weak":"+2{threat}","reward":"1{xp}；特殊：事件-30。","id":"38","name":"女巫蚁","faq":[{"question":"“+1(所有)”是什么意思？","answer":"所有被“尖刺”攻击命中的流放者，都会额外受到1{damage}。"},{"question":"敌人-35 #3（兵蚁#3)的带护甲点网格卡不变化吗?","answer":"是的，敌人-35#3的网格卡保持不变。"},{"question":"敌人-35#3（兵蚁#3）在本场战斗中是否拥有事件-309赋予的特殊能力？","answer":"没有，它不再是“狂奔蚁”了。“狂奔蚁”是个特有称呼。"},{"question":"逃离3是什么意思?","answer":"敌人以3向远离目标的方向移动。2/2敌人-38"}],"original":"ai/FOE-38-26-32-back.webp"},"42":{"behaviors":[[0,"most_hp",4,"喷溅"],[1,"furthest",4,"爪击，爪击"],[3,"closest",6,"爪击，喷溅 +2{damage}"]],"abilities":[{"name":"爪击","die":"blue","body":"3{damage}","grid":["XXX","...","..."],"origin":[1,1.5]},{"name":"喷溅","die":"black","body":"1{durability}，3{damage}","grid":[".X.","XXX","...","..."],"origin":[1,2.5],"originKind":"ranged"}],"weak":"+1{threat}，然后再生。","traits":["再生：治疗X个非弱点生命点。X等于当前威胁值。"],"reward":"2{xp}；特殊：事件-306。","id":"42","name":"幼年蝾螈","faq":[{"question":"对于“再生”效果，具体哪些生命点会被治疗?","answer":"由流放者决定。"},{"question":"“喷溅”效果如何生效？","answer":"先在被命中部位的一件护甲上放置一个磨损指示物(若有护甲)，之后正常造成伤害。"}],"original":"ai/FOE-42-26-35-back.webp"},"45":{"behaviors":[[0,"most_hp",4,"刺果，逃离4"],[1,"closest",4,"刺果 +1{damage}"],[3,"furthest",6,"刺果 +2{damage}"]],"abilities":[{"name":"刺果","die":"black","body":"4{distance}，2{damage}；随后结算破片。","attackType":"ranged"},{"name":"破片","body":"对刺果目标2{distance}内的另一名流放者，造成蓝色命中骰的1{damage}。"}],"weak":"若攻击者在有效距离内，对其使用刺果。若当前是流放者的回合，还要逃离2。","reward":"1{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件木制物品。","id":"45","name":"狗头人投果手","faq":[{"question":"“刺果+X”是否也会增加“破片”的伤害？","answer":"是的。“破片”是“刺果+X”攻击的一部分。"},{"question":"弱点效果中的“对攻击者刺果”是什么意思？","answer":"若发起攻击的流放者处于“刺果”的攻击范围内，则对该流放者结算“刺果”攻击。"},{"question":"结算“对攻击者刺果”时，是否也会触发“破片”效果？","answer":"是的，“破片”是“刺果”攻击的一部分。"},{"question":"若使用游荡者的“误导”技能，弱点效果如何结算？","answer":"被攻击的敌人忽略“对攻击者刺果”效果，随后视因误导而发起攻击的敌人为攻击者执行逃离。"},{"question":"逃离4是什么意思?","answer":"敌人以4向远离目标的方向移动。"}],"original":"ai/FOE-45-26-38-back.webp"},"48":{"behaviors":[[0,"most_hp",4,"齐射"],[1,"furthest",4,"齐射 +1{damage}"],[3,"furthest",6,"齐射 +2{damage}"]],"abilities":[{"name":"齐射","die":"red","body":"选择至多2名流放者：2–4{distance}，1{damage}。","attackType":"ranged"}],"weak":"+1{threat}","reward":"2{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件石制物品。","id":"48","name":"蜥精弓箭手","faq":[{"question":"对于“齐射”效果，蜥精能否以距离不同的流放者为目标？","answer":"可以!不要求2名目标流放者与蜥精的距离0一样，只要都处于2-4{distance}内就行。"}],"original":"ai/FOE-48-26-41-back.webp"},"49":{"behaviors":[[0,"closest",6,"挥砍，盾撞"],[1,"furthest",7,"挥砍 +1{damage}，盾撞"],[3,"furthest",8,"挥砍 +2{damage}，盾撞"]],"abilities":[{"name":"盾撞","body":"目标进行力量13检定。失败：事件-412。","grid":["XXX",".@.","..."],"choice":true},{"name":"挥砍","die":"blue","body":"1{damage}","grid":["XXX",".@.","..."]}],"weak":"+1{threat}","reward":"2{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件石制物品。","id":"49","name":"蜥精海盜","faq":[{"question":"“盾撞”的位置网格中，虚线选框代表什么?","answer":"代表“盾撞”仅从虚线选框方格中选择一名流放者作为目标(若有需要，由玩家选择)。(参见：位置网格，第21页）"}],"original":"ai/FOE-49-26-44-back.webp"},"50":{"behaviors":[[0,"most_hp",6,"踢飞，嘲笑"],[1,"closest",6,"挥斧，踢飞"],[3,"closest",6,"挥斧，踢飞，嘲笑"]],"abilities":[{"name":"挥斧","die":"red","body":"2{damage}","grid":["XXX",".@.","..."]},{"name":"嘲笑","body":"+2{threat}。每名流放者进行智力12检定；失败：-1{sp}。"},{"name":"踢飞","die":"yellow","body":"1{damage}，然后目标进行敏捷18检定。失败：事件-412。","grid":["XXX",".@.","..."],"choice":true}],"weak":"若攻击者与其相邻，对攻击者使用踢飞。","reward":"2{xp}；特殊：事件-37。","id":"50","name":"船长之厄基","faq":[{"question":"“踢飞”的位置网格中，虚线选框代表什么?","answer":"代表“踢飞”仅从虚线选框方格中选择一名流放者作为目标(若有需要，由玩家选择)。(参见：位置网格，第21页）"},{"question":"若我已没有剩余{sp}，再要失去时会发生什么？","answer":"无事发生。"},{"question":"对于这个弱点效果，“踢飞”会以谁为目标？","answer":"以发起攻击的流放者为目标。若对弱点的伤害是由诸如陷阱等来源(非流放者直接造成的），则无事发生。"},{"question":"若击伤弱点的攻击者不在“踢飞”的攻击范围内，但是有其他流放者在，“踢飞”会更换目标吗?","answer":"不会，“踢飞”仅会尝试攻击击伤弱点的攻击者。"},{"question":"若使用游荡者的“误导”技能，使击伤弱点的攻击者变为其他敌人，“踢飞”会对此敌人触发吗？","answer":"不会，按照图示，“踢飞”只能以敌人的敌方（即流放者)为目标，因此不会触发。"},{"question":"对于攻击后触发的效果，“踢飞”攻击何时视为完成？","answer":"在“踢飞”效果完全结算后(若触发了事件-412，还需包含该事件的完整结算，因为事件-412是“踢飞”攻击的一部分）。2/2敌人-50"}],"original":"ai/FOE-50-26-46-back.webp"},"52":{"behaviors":[[0,"most",2,"刺毛，+4{threat}"],[1,"closest",4,"尾巴链枷，逃离4"],[3,"most",6,"尾巴链枷，刺毛，逃离2"]],"abilities":[{"name":"刺毛","die":"black","body":"5{distance}内的每名流放者受到3{damage}。","attackType":"ranged"},{"name":"尾巴链枷","die":"red","body":"7{damage}","grid":["XXXX","X..X","X..X","XXXX"],"origin":[1.5,1.5],"originKind":"area"}],"weak":"+3{threat}","traits":["游行：将不可通行边界及困难边界视为普通边界。"],"reward":"5{xp}；特殊：事件-111。","id":"52","name":"豺蟒","faq":[{"question":"豺蟒能否在底座占据不可穿越格边的情况下结束回合?","answer":"可以。"},{"question":"豺蟒攻击后，会向远离哪名流放者的方向逃离？","answer":"会向远离其中一名被攻击流放者的方向逃离（若攻击了多名流放者，由玩家选择）。"},{"question":"代表什么？","answer":"获得键钥-502。"}],"original":"ai/FOE-52-26-48-back.webp"},"59":{"behaviors":[[0,"most_hp",5,"劈砍"],[1,"most_hp",5,"劈砍 +1{damage}"],[3,"closest",5,"劈砍 +2{damage}，起身"]],"abilities":[{"name":"劈砍","die":"blue","body":"3{damage}","grid":[".X.",".@.","..."]}],"weak":"+2{threat}","traits":["骸骨堆：此敌人将被击败时，将其模型侧倒，移除所有伤口，并将网格卡翻到骸骨堆一面。"],"reward":"2{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件石制物品。","id":"59","name":"蹒跚骷髅","faq":[{"question":"“复苏”是什么意思?","answer":"“复苏”规则详见骷髅网格卡的背面。"},{"question":"“复苏”会恢复护甲点上的护甲指示物吗?","answer":"不会。"},{"question":"若将骷髅击败的伤害中也击伤了弱点，弱点效果会触发吗?因为骷髅被击败是变成骸骨堆，而不是像通常敌人一样直接移除了。","answer":"不会，弱点效果不触发。"},{"question":"若处于隐藏状态的游荡者踩踏骸骨堆或为其进行治疗，会失去隐藏状态吗?","answer":"不会。游荡者不会失去隐藏状态。"}],"original":"ai/FOE-59-26-52-back.webp"},"60":{"behaviors":[[0,"most_hp",4,"箭矢"],[1,"most_hp",4,"箭矢 +1{damage}"],[3,"furthest",4,"箭矢 +2{damage}，起身"]],"abilities":[{"name":"箭矢","die":"red","body":"6{distance}，2{damage}。","attackType":"ranged"}],"weak":"持续：箭矢距离-4{distance}。","traits":["骸骨堆：此敌人将被击败时，将其模型侧倒，移除所有伤口，并将网格卡翻到骸骨堆一面。"],"reward":"2{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件石制物品。","id":"60","name":"骷髅弓箭手","faq":[{"question":"“复苏”是什么意思?","answer":"“复苏”规则详见骷髅网格卡的背面。"},{"question":"“复苏”会恢复护甲点上的护甲指示物吗?","answer":"不会。"},{"question":"若我击伤了其中一名骷髅弓箭手的弱点,两名弓箭手的攻击距离都会缩短吗？","answer":"不会，仅弱点被击伤的那名弓箭手攻击距离缩短。"},{"question":"若此敌人在自身回合的移动中弱点被击伤(如陷阱),导致攻击距离缩短，会如何处理？","answer":"此敌人会立即根据剩余移动力和新的攻击距离，来重新选择目标，因此可能会更换目标。"},{"question":"若处于隐藏状态的游荡者踩踏骸骨堆或为其进行治疗，会失去隐藏状态吗？","answer":"不会。游荡者不会失去隐藏状态。"}],"original":"ai/FOE-60-26-56-back.webp"},"61":{"behaviors":[[0,"closest",3,"切砍，+4{threat}"],[1,"closest",5,"回旋斩"],[3,"most",6,"回旋斩，起身"]],"abilities":[{"name":"切砍","die":"yellow","body":"4{damage}","grid":["XXX",".@.","..."]},{"name":"回旋斩","die":"blue","body":"5{damage}","grid":["XXX","X@X","XXX"]}],"weak":"+2{threat}","traits":["盾牌：免疫恰好只有1点伤害的攻击轨迹。附加伤害不受影响。","骸骨堆：此敌人将被击败时，将其模型侧倒，移除所有伤口，并将网格卡翻到骸骨堆一面。"],"reward":"2{xp}；特殊：小型-48。","id":"61","name":"骷髅战士","faq":[{"question":"此敌人的“盾牌”能力如何生效?","answer":"若攻击轨迹只由一点伤害构成(如仅一点}，或仅一点定向伤害），则不论是否是穿甲伤害，此敌人将对此攻击免疫。注意，此效果判定依据为即将适用的整个攻击轨迹情况，而非伤害实际会造成的损伤。"},{"question":"“盾牌”能力与附加伤害如何互动？","answer":"按游戏规则，只有先对敌人造成基础的伤害，才能进一步造成附加伤害(如标记、暴击点)。若基础的一点伤害被“盾牌”免疫了，那就无法进一步造成任何附加伤害。"},{"question":"若将骷髅击败的伤害中也击伤了弱点，弱点效果会触发吗?因为骷髅被击败是变成骸骨堆，而不是像通常敌人一样直接移除了。","answer":"不会，弱点效果不触发。"},{"question":"按盾牌的效果,若骷髅战士剩一点生命点时就无敌了？","answer":"不是！它仅对只由一点伤害构成的攻击轨迹免疫。多点伤害构成的攻击轨迹就可以突破“盾牌”的效果！注意，伤害指技能或武器即将适用的效果，而损伤则是对生命点适用伤害所得到的结果(例如，因轨迹和网格卡情况只能造成一点损伤的2点伤害攻击轨迹，是不会被免疫的)。"}],"original":"ai/FOE-61-26-59-back.webp"},"67":{"behaviors":[[0,"closest",6,"捅刺"],[1,"most_hp",6,"捅刺 +1{damage}"],[3,"most_hp",6,"捅刺，捅刺"]],"abilities":[{"name":"捅刺","die":"black","body":"3{damage}","grid":[".X.",".@.","..."]}],"weak":"若可能，对一名相邻流放者使用捅刺。","traits":["诀别：每当一名地精步兵被击败，+1{threat}。"],"reward":"2{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件石制物品。","id":"67","name":"地精步兵","faq":[{"question":"对于“临终托付”效果，每击败一名地精步兵，是否都会+1，即使是场上最后一名地精步兵也要加？","answer":"是的，每击败一名地精步兵，{threat}+1。3/3敌人-67"}],"original":"ai/FOE-67-26-62-back.webp"},"68":{"behaviors":[[0,"closest",5,"双重射击"],[1,"furthest",5,"双重射击 +1{damage}"],[3,"most",5,"双重射击 +2{damage}"]],"abilities":[{"name":"双重射击","die":"red","body":"选择至多2名流放者：3{distance}，2{damage}。","attackType":"ranged"}],"weak":"+2{threat}","traits":["诀别：每当地精投箭手被击败，+1{threat}。"],"reward":"2{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件石制物品。","id":"68","name":"地精投箭手","faq":[{"question":"对于“临终托付”效果,每击败一名地精投箭手，是否都会+1，即使是场上最后一名地精投箭手也要加？","answer":"是的，每击败一名地精投箭手，{threat}+1。3/3敌人-68"}],"original":"ai/FOE-68-26-65-back.webp"},"69":{"behaviors":[[0,"closest",3,"绞碎，+2{threat}"],[1,"furthest",4,"绞碎 +1{damage}"],[3,"most",4,"屠杀"]],"abilities":[{"name":"绞碎","die":"yellow","body":"3{damage}","grid":["...","X..","X.."],"origin":[1,1.5]},{"name":"屠杀","die":"blue","body":"4{damage}","grid":[".X.","X.X","X.X",".X."],"origin":[1,1.5]}],"weak":"增加1个愤怒标记。","traits":["愤怒：每当地精被击败，在这里放置1个愤怒标记（护甲方块）。每有1个愤怒标记，+1{damage}且+1{move}。"],"reward":"2{xp}；特殊：事件-72。","id":"69","name":"坑洞头头加鲁克","faq":[{"question":"O 代表什么？","answer":"获得 键钥-502"}],"original":"ai/FOE-69-26-67-back.webp"},"72":{"behaviors":[[0,"closest",6,"尾巴横扫"],[1,"most",6,"呕吐"],[3,"most",6,"尾巴横扫，呕吐"]],"abilities":[{"name":"呕吐","die":"yellow","body":"2{distance}内的每名流放者：1{durability}、3{damage}。","attackType":"area"},{"name":"尾巴横扫","die":"blue","body":"4{damage}","grid":["XXX","...","..."],"origin":[1,1.5]}],"weak":"所有相邻流放者失去1{durability}。","traits":["腐蚀黏液：每当相邻流放者攻击此生物，攻击者失去1{durability}，部位由玩家选择。"],"reward":"2{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件石制物品。","id":"72","name":"巨型蝾螈","faq":[{"question":"“呕吐”效果如何生效？","answer":"先往穿戴在命中部位的一件护甲上放置一个磨损指示物，然后再适用伤害。"},{"question":"“腐蚀性黏液”效果如何生效？","answer":"该流放者需选择一件穿戴的护甲(仍有耐久的)，在上面放置一个磨损指示物。"},{"question":"弱点效果如何生效?","answer":"所有相邻的流放者均需选择一件穿戴的护甲（仍有耐久的)，在上面放置一个磨损指示物。"},{"question":"对于“腐蚀性黏液”/弱点效果，我能否选择背包中的护甲？","answer":"不能，仅可选择穿戴的护甲。"}],"original":"ai/FOE-72-25-0-back.webp"},"73":{"behaviors":[[0,"most",5,"喷射"],[1,"closest",6,"尾巴重锤"],[3,"most",6,"尾巴重锤，喷射"]],"abilities":[{"name":"喷射","die":"yellow","body":"4{distance}内的每名流放者受到1{damage}。若没有完全格挡，再失去5{hp}。","attackType":"ranged"},{"name":"尾巴重锤","die":"blue","body":"2{distance}内的每名流放者受到6{damage}。","attackType":"melee"}],"weak":"治疗3个非弱点生命点。","traits":["黏液反击：被4{distance}内没有黏液状态的流放者伤害时，在攻击者肖像上放置黏液标记（硬化方块）。","黏液（持续）：所有掷骰-5，直到通过休息刷新。"],"reward":"2{xp}、1件石制物品、键钥-40。","id":"73","name":"黏液领主","faq":[{"question":"“黏液反击”效果如何生效?","answer":"若你处于敌人4内，且对其适用任何伤害(即使实际未造成损伤)，需在你的肖像上放置一个硬化方块，代表你处于“黏液糊身”状态。"},{"question":"“黏液糊身”状态如何生效?","answer":"你的所有掷骰结果均-5。当你{rest}休息时，移除黏液标记（硬化方块）。"},{"question":"对于这个弱点效果，哪些生命点会被治疗?","answer":"由流放者决定。"},{"question":"若我的某次伤害击败了黏液领主，“黏液反击”仍会结算吗?","answer":"不会，它与弱点效果结算方式相同，需在附加伤害后结算。"},{"question":"代表什么？","answer":"获得键钥-502。"},{"question":"若伤害来源并非一名流放者(如陷阱、施毒技能)，“黏液反击”会触发吗?","answer":"不会。2/2敌人-73"}],"original":"ai/FOE-73-25-2-back.webp"},"81":{"behaviors":[[0,"furthest",5,"猛扑，逃离3"],[1,"closest",5,"猛咬，逃离3"],[3,"furthest",6,"猛咬，猛扑"]],"abilities":[{"name":"猛咬","die":"yellow","body":"3{damage}，-1{sp}","grid":[".X.","...","..."],"origin":[1,1.5]},{"name":"猛扑","die":"red","body":"1{damage}。若本回合此敌人已移动至少2格，+3{damage}。","grid":[".X.","...","..."],"origin":[1,1.5]}],"weak":"+1{threat}。若当前是流放者的回合，还要逃离2。","traits":["狼群之力：查看场上对应的事件卡。"],"reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件石制物品。","id":"81","name":"猎狼","faq":[{"question":"若我已没有剩余{sp}，再要失去时会发生什么？","answer":"无事发生。"},{"question":"“最多只能承受3点损伤”是什么意思?","answer":"当你要在已放置3个损伤指示物的网格卡上放置损伤指示物时，不要放置。不过你仍可照常移除护甲方块。"},{"question":"对于“猛扑”的+3伤害触发条件，既然此敌人底座占据了2个方格，那是不是走一步就算移动了2格呢，因为看起来是敌人前半头和后半头都前进了一格？","answer":"不是。只能计算其底座前一个方格移动的方格数量，不计算后一个方格跟着的移动。(例如：若敌人向北移动一个方格，即使模型后半部分也随之移动了一个方格，仍计为只移动了一个方格）。3/3敌人-81"}],"original":"ai/FOE-81-25-5-back.webp"},"82":{"behaviors":[[0,"least_hp",5,"拖拽"],[1,"least_hp",5,"拖拽 +1{damage}"],[3,"most",6,"撕裂"]],"abilities":[{"name":"拖拽","die":"black","body":"2{damage}。向图示×方向移动4格，同时拉动目标。","grid":[".X.","...","..."],"origin":[1,1.5]},{"name":"撕裂","die":"blue","body":"2{distance}内的每名流放者受到4{damage}。","attackType":"melee"}],"weak":"攻击者失去1{sp}。","traits":["狼群之力：查看场上对应的事件卡。"],"reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件石制物品。","id":"82","name":"雪狼","faq":[{"question":"若我已没有剩余{sp}，再要失去时会发生什么？","answer":"无事发生。"},{"question":"“最多只能承受3点损伤”是什么意思？","answer":"当你要在已放置3个损伤指示物的网格卡上放置损伤指示物时，不要放置。不过你仍可照常移除护甲方块。"},{"question":"“拖拽”效果如何结算？","answer":"雪狼必须选择流放者可跟随的路径(如不穿过其他敌人)，且雪狼每移动一格，流放者就立刻被拉近到雪狼先前所在的那一格。"},{"question":"若使用游荡者的“误导”技能，弱点效果如何结算？","answer":"该效果会以敌人为目标，因此忽略{sp}的损失。3/3敌人-82"}],"original":"ai/FOE-82-25-8-back.webp"},"85":{"behaviors":[[0,"furthest",4,"生成3，+4{threat}"],[1,"closest",4,"生成4"],[3,"furthest",5,"生成3，飞溅"]],"abilities":[{"name":"生成X","body":"从橙浆怪正上方1英寸处，落下X个磨损指示物的位置各加入1只史莱姆。然后，若尚未抽取，抽取敌人-86。"},{"name":"飞溅","die":"black","body":"4{distance}，1{durability}、4{damage}。","attackType":"ranged"}],"weak":"生成2。","reward":"6{xp}；特殊：事件-70。","id":"85","name":"黏液橙浆怪","faq":[{"question":"“生成X”效果如何生效？","answer":"用手在距离黏液橙浆怪模型头顶2.5厘米高度的位置，丢下X个磨损指示物，砸到模型头上。然后这些磨损指示物会飞落到地图上不同位置，来代表生成的敌人-86（史莱姆)。史莱姆可与流放者共享方格，但不可与黏液橙浆怪或其他史莱姆共享方格。若史莱姆通过此方式落到流放者方格内，不会触发“酸性黏液”效果。若史莱姆落到地图外，将其放在距离落点最近的可放置方格上（也可以重新丢，如果你愿意的话）。"},{"question":"“飞溅”效果如何生效?","answer":"先往穿戴在命中部位的一件护甲上放置一个磨损指示物，然后再适用伤害。"},{"question":"对于3{threat}的行为，如果其中的“飞溅”攻击不到流放者(比如距离过远)，那其中的“生成3”还需要执行吗？","answer":"还是需要。2/2敌人-85"}],"original":"ai/FOE-85-25-10-back.webp"},"86":{"behaviors":[[0,"closest",1,"黏质"],[5,"closest",2,"黏质，黏质"]],"abilities":[{"name":"黏质","body":"每名相邻流放者失去以下之一：1{hp}、1{durability}或1{sp}。"}],"traits":["酸性黏液：史莱姆不会阻挡流放者移动，可与一名流放者共享方格，但史莱姆之间不能共享方格。流放者进入史莱姆所在方格时，失去1{durability}，部位由玩家选择。"],"reward":"无。","id":"86","name":"史莱姆","faq":[{"question":"对于“黏质”效果，若我已没有{durability}和{sp}，会如何处理？","answer":"那你必须选择失去{hp}。"},{"question":"流放者跟与其共享方格的史莱姆算相邻吗?","answer":"算，方格本身视为与自身相邻，因此共享同一方格的所有单位均视为相邻。"},{"question":"强化指示物与“黏质”效果如何互动?","answer":"若你选择失去{hp}，则会额外失去1{hp};但若你选择失去{durability}或{sp}，则不受强化指示物影响。"},{"question":"若史莱姆生成(飞落)在有标记方块或陷阱的方格内，在考虑一些“进入方格”触发的效果时，算进入该方格吗？","answer":"算，就相关技能效果而言，生成视为“进入”方格。"},{"question":"若史莱姆移动或生成在警戒指示物或隐藏游荡者方格内，会发生什么？","answer":"警戒指示物会被移除，且游荡者失去隐藏状态。"},{"question":"当我需要失去{durability}时，能否选择背包中的护甲?","answer":"不能，仅可选择穿戴的护甲。2/2敌人-86"}],"original":"ai/FOE-86-25-12-back.webp"},"96":{"behaviors":[[0,"closest",5,"撕扯"],[1,"furthest",7,"撕扯，哀恸"],[3,"closest",9,"撕扯 +2{damage}，哀恸"]],"abilities":[{"name":"哀恸","body":"3{distance}内的每名流放者进行魅力13检定。失败：-1{sp}且-1{mp}。","attackType":"area"},{"name":"撕扯","die":"yellow","body":"2{damage}","grid":[".X.","...","..."],"origin":[1,1.5]}],"weak":"哀恸。","reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"96","name":"幼年雾牙","faq":[{"question":"强化指示物会影响“哀恸\"效果导致的和6 {sp}{mp}损失吗？","answer":"不会，你仍仅失去1{sp}和1{mp}，因为强化指示物仅影响伤害以及{hp}损失。4/4敌人-96"}],"original":"ai/FOE-96-25-16-back.webp"},"97":{"behaviors":[[0,"closest",5,"割裂"],[1,"furthest",7,"酸性吐息"],[3,"closest",9,"割裂，割裂"]],"abilities":[{"name":"割裂","die":"black","body":"2{damage}","grid":[".X.","X.X","..."],"origin":[1,1.5]},{"name":"酸性吐息","die":"red","body":"2{damage}","grid":["XXX",".X.","...","..."],"origin":[1,2.5],"originKind":"area"}],"weak":"酸性吐息。","reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"97","name":"雾牙","faq":[{"question":"若此敌人的弱点被击伤,它会在执行弱点效果的“酸性吐息”攻击前移动吗？","answer":"不会，它会在不移动的情况下，来攻击图示范围内尽可能多的流放者(若需要可以转向)。"},{"question":"游荡者的“误导”技能触发的弱点效果如何结算？","answer":"正常结算，虽然是敌人击伤的弱点，它仍会尝试用“酸性吐息”攻击图示范围内尽可能多的流放者。若图示范围内无流放者，则不执行任何操作。"}],"original":"ai/FOE-97-25-20-back.webp"},"98":{"behaviors":[[0,"furthest",4,"威吓"],[1,"closest",0,"凝聚"],[3,"most",4,"威吓，凝聚"]],"abilities":[{"name":"威吓","body":"5{distance}内的每名流放者进行感知18检定。失败：在最高的属性上放置1个伤口；受伤属性视为0，战斗结束时恢复。"},{"name":"凝聚","body":"将一个已被击败的敌人放回地图，位置尽可能靠近雾狮狼。若没有可放回的敌人，则使用威吓。"}],"weak":"威吓。","traits":["强化光环：所有其他敌人的伤害攻击与能力均+3{damage}。"],"reward":"3{xp}；特殊：事件-85。","id":"98","name":"雾狮狼","faq":[{"question":"我是否会多次受到“威吓”的负面效果？","answer":"是的!每次在“威吓”检定中失败，你当前最高(注意放有损伤的视为0)的基础属性会被标记为受损。若有两个基础属性并列最高，由玩家选择其中一个。"},{"question":"通过“凝聚”效果复活的敌人，其护甲点也会恢复吗？","answer":"是的，此敌人会以满生命点、满护甲点状态复活。"},{"question":"已被击败的雾狮狼能否通过“凝聚”效果复活自身？","answer":"不能，因为已被击败的敌人不会激活。可以。例如，雾狮狼通过“所有敌人”类型的威胁卡执行凝聚,复活了被击败的敌人，那么刚复活的敌人就会按其先攻权正常激活。由于雾狮狼先攻权编号为0，复活敌人的激活会排在雾狮狼之后。"},{"question":"若“威吓”命中游荡者的警戒指示物，会发生什么?","answer":"无事发生。(但如果处于隐藏状态的游荡者也在范围内，“威吓”效果仍会适用至该游荡者)。"}],"original":"ai/FOE-98-25-22-back.webp"},"106":{"behaviors":[[0,"most_hp",8,"切割"],[1,"most",7,"大颚"],[3,"furthest",9,"切割 +3{damage}"]],"abilities":[{"name":"切割","die":"black","body":"1{damage}","grid":[".X.",".@.","..."]},{"name":"大颚","die":"blue","body":"2{damage}","grid":["XXX",".@.","..."]}],"weak":"持续：若弱点已受伤，忽略钳制。","traits":["钳制：流放者试图移出相邻方格时，进行敏捷11检定。失败：不能离开该格，-3{hp}，并失去所有剩余移动。"],"reward":"2{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件石制物品。","id":"106","name":"侵略蚁","faq":[{"question":"具体是什么移动会触发“钳夹”效果?","answer":"流放者使用给予！图标的能力(包括基本移动行动)移动时(如想脱离侵略蚁相邻位置或从侵略蚁身边经过)，会触发“钳夹”效果。"},{"question":"变位、推远、拉近或放置类能力会触发“钳夹”效果吗？","answer":"不会,仅给予!图标的能力会触发“钳夹”效果。"},{"question":"若我击伤其中一只侵略蚁的弱点，所有侵略蚁都会停止使用“钳夹”吗？","answer":"不会，仅弱点被击伤的那只侵略蚁会停止使用。"}],"original":"ai/FOE-106-25-27-back.webp"},"108":{"behaviors":[[0,"closest",2,"入侵"],[1,"closest",4,"入侵 -1{hp}"],[3,"furthest",7,"精神冲击"]],"abilities":[{"name":"入侵","body":"结算所有侵略蚁的威胁0行为。随后，每名流放者每相邻一只蚂蚁，-1{hp}。若没有侵略蚁，则改为+7{threat}。"},{"name":"精神冲击","die":"red","body":"选择7{distance}内的流放者，造成3{damage}；该目标5{distance}内的所有其他流放者也受到3{damage}。"}],"weak":"+1{threat}","reward":"2{xp}；特殊：事件-97。","id":"108","name":"萨满蚁","faq":[{"question":"1{threat}行为的“入侵-1{hp}”如何生效?","answer":"每只相邻的蚂蚁会导致流放者-2{hp}，而非通常的-1{hp}。"},{"question":"萨满蚁算侵略蚁吗?","answer":"不算。它属于蚂蚁，但不属于侵略蚁。"},{"question":"代表什么？","answer":"获得键钥-502。2/2敌人-108"}],"original":"ai/FOE-108-25-29-back.webp"},"111":{"behaviors":[[0,"all",null,"谜语"],[3,"most",10,"扫射"]],"abilities":[{"name":"扫射","die":"red","body":"尽可能飞越更多流放者。对每名被飞越的流放者造成6{damage}，每次扫射对同一名流放者至多一次。"},{"name":"谜语","body":"朝威胁-689移动10{move}，然后通过事件-103，向所有流放者提出谜语。"},{"name":"灵能尖啸","body":"+2{threat}，每名流放者-4{hp}。"}],"weak":"+1{threat}","traits":["飞行：将不可通行和困难边界视为普通边界，忽略陷阱；可穿过流放者所在方格，但不能在其上结束移动。"],"reward":"5{xp}；特殊：事件-86。","id":"111","name":"奇枭","faq":[{"question":"0 代表什么？","answer":"获得 键钥-502。"},{"question":"此敌人是否同时属于首领和杂兵?","answer":"是的！若你抽取“首领”或“杂兵”类型的威胁卡，此敌人都会激活；若抽取“所有敌人”类型的威胁卡，仅激活一次。"},{"question":"奇枭“扫射”流放者的顺序是什么？","answer":"移动路径首先要能攻击到最多流放者,其次应尽量缩短移动距离；若仍有多种选择，由玩家决定攻击顺序与具体移动路径。"},{"question":"若战士在“扫射”期间使用“守护”技能，会发生什么？","answer":"战士受到两次扫射伤害(守护目标本应受到的一次，外加战士自己被扫射到的一次)。被守护的流放者不会受到扫射伤害。"},{"question":"若奇枭“扫射”穿过处于隐藏状态的游荡者，会发生什么？","answer":"游荡者会受到伤害，且失去隐藏状态(只有当奇枭穿过了游荡者所在方格时才会这样)。"}],"original":"ai/FOE-111-25-31-back.webp"},"115":{"behaviors":[[0,"most",4,"盘旋击，进食"],[4,"none",null,"结算威胁0行为两次"]],"abilities":[{"name":"盘旋击","die":"black","body":"5{damage}。若没有完全格挡，将流放者推远4格。","grid":[".XX.","X..X","X..X",".XX."],"origin":[1.5,1.5]},{"name":"进食","body":"向威胁-689移动8{move}。若未受伤，增加2个力量标记；若已受伤，治疗2个生命点并+1{threat}。"}],"weak":"盘旋击。","traits":["防御潜行：当至少占据一个旋涡方格时，免疫来自非相邻流放者的范围和远程伤害。","游行：将困难边界视为普通边界。"],"reward":"8{xp}；特殊：事件-247。","id":"115","name":"古老豺蟒","faq":[{"question":"“防御性下潜”中的“漩涡”指什么？","answer":"所有漩涡方格以及{xp}方格（不包括岩石）。"},{"question":"什么是漩涡方格?","answer":"带有方向箭头的方格。流放者在一回合内可多次使用“乘潮而行”。"},{"question":"附加伤害如何生效?","answer":"附加伤害(如标记、冲突合唱)没有能力类型分类,所以只要基础的伤害没有受“防御性下潜”影响，附加伤害即可生效。"},{"question":"“推远”效果如何结算？","answer":"选择一个距离敌人更远的相邻方格,将你的流放者放到该格;重复此操作，直至完成指定推远次数，或无更远的相邻方格可用。"},{"question":"若无指示物，我能否使用“深奥学识”技能?","answer":"不能，该反应技能需要消耗一个{xp}。"},{"question":"“深奥学识”技能能否在非战斗时使用？","answer":"不能，因为该技能需要消耗连击。2/2敌人-115"}],"original":"ai/FOE-115-25-33-back.webp"},"125":{"behaviors":[[0,"closest",6,"穿刺"],[1,"most",6,"迅速连击"],[3,"most",6,"穿刺 +2{durability}"]],"abilities":[{"name":"迅速连击","die":"blue","body":"4{damage}","grid":[".X.","X@X",".X."]},{"name":"穿刺","die":"black","body":"1{durability}、3{damage}","grid":[".X.",".X.",".@."]}],"weak":"+2{threat}","traits":["看着我：相邻流放者移开后攻击狗头人守卫以外的敌人时，该流放者失去2{durability}。"],"reward":"2{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件石制物品。","id":"125","name":"狗头人守卫","faq":[{"question":"“穿刺”效果如何生效?","answer":"若可能，先在命中骰确定命中部位的护甲上添加相应数量的磨损指示物（累积数量不超会过该护甲的{durability})，之后正常造成伤害。"},{"question":"“休想分心”中的“移动离开”指什么？","answer":"流放者通过使用！!图标的行动或技能，从相邻方格移动至非相邻方格。当相邻流放者进入非相邻方格时，立即放置2个磨损指示物(可任意选择放置位置）；放置、变位、推远或拉近类效果不算“移动”。"},{"question":"“休想分心”中的“攻击”指什么？","answer":"对名称不为“狗头人守卫”的敌人，使用基本攻击或可以造成伤害的技能。在攻击结算完后放置2个磨损指示物（可任意选择放置位置）；对于同时以狗头人守卫与非狗头人守卫为目标的攻击，“休想分心”也仍会触发。"},{"question":"为“休想分心”放置2个磨损指示物时，能否分别放在不同装备上？","answer":"可以。3/3敌人-125"}],"original":"ai/FOE-125-25-36-back.webp"},"126":{"behaviors":[[0,"most_hp",4,"毒刺果"],[1,"most_hp",5,"毒刺果 +1{damage}"],[3,"furthest",6,"毒刺果 +2{damage}"]],"abilities":[{"name":"毒刺果","die":"red","body":"4{distance}，1{damage}。若没有完全格挡，-2{hp}。然后结算碎片。","attackType":"ranged"},{"name":"碎片","body":"对毒刺果目标2{distance}内的另一名流放者，造成蓝色命中骰的1{damage}。"}],"weak":"若攻击者在有效距离内，对其使用毒刺果。若当前是流放者的回合，还要逃离2。","reward":"2{xp}；特殊：中型-42转为B。","id":"126","name":"狗头人刺果射手","faq":[{"question":"“未完全阻挡”是什么意思？","answer":"是该攻击导致你失去了{hp}的意思。此时你将再额外-2{hp}。"},{"question":"对于攻击后触发的效果，“毒刺果”攻击何时视为完成？","answer":"在“破片”效果完全结算后。因为“破片”是“毒刺果”攻击的一部分，被列在“毒刺果”的描述中，并不是独立于毒刺果的攻击（不是单独提及的那种）。"},{"question":"“毒刺果+X”是否也会增加“破片”的伤害?","answer":"是的。“破片”是“毒刺果+X”攻击的一部分。"},{"question":"弱点效果中的“对攻击者毒刺果”是什么意思?","answer":"若发起攻击的流放者处于“毒刺果”的攻击范围内，则对该流放者结算“毒刺果”攻击。"},{"question":"结算“对攻击者毒刺果”时，是否也会触发“破片”效果？","answer":"会，“破片”是“毒刺果”攻击的一部分。"},{"question":"若使用游荡者的“误导”技能，弱点效果如何结算？","answer":"忽略“对攻击者毒刺果”效果，随后视因误导而发起攻击的敌人为攻击者执行逃离。3/3敌人-126"}],"original":"ai/FOE-126-25-39-back.webp"},"127":{"behaviors":[[0,"closest",5,"超级戳刺，+4{threat}"],[1,"most_hp",6,"超级猛击"],[3,"most",5,"超级戳刺 +2{damage}"]],"abilities":[{"name":"超级猛击","die":"black","body":"7{damage}","grid":[".X.",".@.","..."]},{"name":"超级戳刺","die":"blue","body":"3{distance}内的每名流放者受到4{damage}。","attackType":"melee"}],"traits":["借势人群：只要有至少一名相邻流放者，此敌人免疫来自非相邻流放者的伤害。","若你被超级假人击败，抽取事件-12。"],"reward":"6{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"127","name":"超级假人","faq":[{"question":"场上被击昏的流放者可以被算作“利用人群”效果中的相邻流放者吗?","answer":"是的。"},{"question":"代表什么？","answer":"获得 键钥-502。"},{"question":"此敌人是否同时属于首领和杂兵?","answer":"是的!若你抽取“首领”或“杂兵”类型的威胁卡,此敌人都会激活;若抽取“所有敌人”类型的威胁卡，仅激活一次。"}],"original":"ai/FOE-127-25-41-back.webp"},"129":{"behaviors":[[0,"closest",4,"寒冰劈砍"],[1,"closest",4,"寒冰劈砍 +2{damage}"],[3,"most",4,"寒冰劈砍 +4{damage}"]],"abilities":[{"name":"寒冰劈砍","die":"blue","body":"4{damage}。若没有完全格挡，则冻结。","grid":[".X.","X@X",".X."]},{"name":"冻结","body":"在被攻击流放者的肖像上放置1个冰标记，使用护甲方块表示。"}],"weak":"+2{threat}","reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"129","name":"冰骷髅斧手","faq":[{"question":"冰冻标记具体如何生效?","answer":"参见敌人-132(裹纱鬼)的AI卡！"},{"question":"若有多名流放者被一次“寒冰劈砍”命中，“冻结”效果是按每名流放者单独判定，还是只要有一名流放者未完全阻挡，所有流放者都会被冻结？","answer":"“冻结”效果按每名流放者单独判定。"}],"original":"ai/FOE-129-25-44-back.webp"},"130":{"behaviors":[[0,"closest",0,"冰霜盾牌，+2{threat}"],[1,"most_hp",6,"碎冰击"],[3,"most",6,"冰霜回旋斩"]],"abilities":[{"name":"碎冰击","die":"yellow","body":"7{damage}，然后冻结。","grid":["XXX",".@.","..."]},{"name":"冰霜回旋斩","die":"blue","body":"7{damage}，然后冻结。","grid":["XXX","X@X","XXX"]},{"name":"冻结","body":"在被攻击流放者的肖像上放置1个冰标记，使用护甲方块表示。"},{"name":"冰霜盾牌","body":"本轮免疫伤害。"}],"weak":"+2{threat}","reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"130","name":"冰骷髅战士","faq":[{"question":"冰冻标记具体如何生效?","answer":"参见敌人-132(裹纱鬼)的AI卡！"},{"question":"“冰霜盾牌”中的“对伤害免疫”指什么?","answer":"任何技能或攻击轨迹均无法造成伤害,不会被放置损伤指示物，护甲方块/硬化方块也不会被移除。"},{"question":"“冰霜盾牌”生效期间，我仍能发起攻击吗？","answer":"可以！但攻击本应造成的所有伤害都会被忽略。"},{"question":"一个轮次具体持续多久?","answer":"一个轮次包含一个敌人回合和一个流放者回合。"},{"question":":代表什么？","answer":"获得 键钥-502。"}],"original":"ai/FOE-130-25-46-back.webp"},"131":{"behaviors":[[0,"furthest",4,"冰箭"],[1,"furthest",4,"冰箭 +2{damage}"],[3,"most",4,"冰箭 +4{damage}"]],"abilities":[{"name":"冰箭","die":"red","body":"5{distance}内的每名流放者受到4{damage}。若没有完全格挡，则冻结。","attackType":"ranged"},{"name":"冻结","body":"在被攻击流放者的肖像上放置1个冰标记，使用护甲方块表示。"}],"weak":"持续：若弱点已受伤，冰箭距离-3{distance}。","reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"131","name":"冰骷髅弓手","faq":[{"question":"冰冻标记具体如何生效?","answer":"参见敌人-132(裹纱鬼)的AI卡！"},{"question":"若有多名流放者被一次“冰箭”命中，“冻结”效果是按每名流放者单独判定，还是只要有一名流放者未完全阻挡，所有流放者都会被冻结？","answer":"“冻结”效果按每名流放者单独判定。"},{"question":"若我击伤其中一名冰骷髅弓手的弱点,两名弓手的攻击距离都会缩短吗？","answer":"不会,仅弱点被击伤的那名弓手攻击距离缩短。"},{"question":"若此敌人在自身回合的移动中弱点被击伤(如陷阱),导致攻击距离缩短，应如何处理？","answer":"此敌人会立即根据剩余移动力和新的攻击距离，来重新选择目标，因此可能会更换目标。"}],"original":"ai/FOE-131-25-49-back.webp"},"132":{"behaviors":[[0,"most",4,"精华汲取"]],"abilities":[{"name":"精华汲取","body":"失去1{hp}、1{sp}和1{mp}，范围按图所示。","grid":["...XX...","..XXXX..",".XXXXXX.","XXX..XXX","XXX..XXX",".XXXXXX.","..XXXX..","...XX..."],"origin":[3.5,3.5],"originKind":"area"}],"traits":["灵体：免疫伤害，可穿过流放者所在方格。","冰：肖像上每有1个冰标记，移动-1{move}，最少为1{move}。","消融：作为标准行动，或在与火焰技能相邻时作为反应行动，移除你所有的冰冻标记。"],"reward":"无。","id":"132","name":"裹纱鬼","faq":[{"question":"冰冻标记具体如何生效?","answer":"当你使用！移动时，你的！!移动力总额获得该惩罚;若某移动效果不涉及！!，则冰冻标记对其无影响。"},{"question":"什么叫“火焰”技能？","answer":"任何带“火”字的技能，如“火球术”或“火焰箭”。要与之相邻，流放者必须与该技能效果范围内的任意方格相邻（方格本身视为与自身相邻）。"},{"question":"此敌人能否成为“嘲讽”等技能的目标？","answer":"可以(但所有本应受到的伤害都会被免疫）。"},{"question":"裹纱鬼会触发陷阱吗?","answer":"会。"},{"question":"“精华汲取”会对游荡者的警戒指示物生效吗？","answer":"不会。（但如果处于隐藏状态的游荡者也在范围内，“精华汲取”仍会适用至该游荡者）。"},{"question":"若此敌人移动穿过警戒指示物，会发生什么?","answer":"警戒指示物被移除且游荡者失去隐藏状态。"},{"question":"我能否移除其他流放者的冰冻标记?","answer":"你仅能移除自己的冰冻标记。"}],"original":"ai/FOE-132-25-51-back.webp"},"140":{"behaviors":[[0,"closest",6,"穿刺"],[1,"most",6,"穿刺 +1{damage}"],[3,"most",6,"穿刺，穿刺"]],"abilities":[{"name":"穿刺","die":"black","body":"3{damage}。若没有完全格挡，失去1{durability}，部位由玩家选择。","grid":[".X.",".X.",".@."]}],"weak":"+1{threat}","reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"140","name":"狗头人长枪手","faq":[{"question":"“未完全阻挡”是什么意思？","answer":"是该攻击导致你失去了{hp}的意思。此时失去{hp} 的流放者选择一件穿戴的护甲(仍有耐久的)，在上面放置一个磨损指示物。"},{"question":"若“穿刺”攻击命中了两名目标，流放者是否需单独判定攻击是否“完全阻挡”?","answer":"是的，每名被命中的流放者需独立判定自己是否完全阻挡了攻击，分别考虑耐久损失。"},{"question":"代表什么？","answer":"获得 键钥-502。3/3敌人-140"}],"original":"ai/FOE-140-25-54-back.webp"},"144":{"behaviors":[[0,"closest",2,"刺果强轰"],[1,"most",4,"刺果强轰 +1{damage}"],[3,"most",5,"刺果强轰 +2{damage}"]],"abilities":[{"name":"刺果强轰","die":"blue","body":"3{distance}内的每名流放者受到2{damage}。若没有完全格挡，-4{hp}。"}],"weak":"若攻击者在有效距离内，对其使用刺果强轰。若当前是流放者的回合，还要逃离2。","reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"144","name":"狗头人刺果炮手","faq":[{"question":"“未完全阻挡”是什么意思？","answer":"是该攻击导致你失去了{hp}的意思。此时你将再额外-4{hp}。"},{"question":"弱点效果中的“对攻击者刺果强轰”是什么意思？","answer":"若发起攻击的流放者处于“刺果强轰”的攻击范围内，则对该流放者结算“刺果强轰”攻击。"},{"question":"若使用游荡者的“误导”技能，弱点效果如何结算？","answer":"忽略“对攻击者刺果强轰”效果，随后视因误导而发起攻击的敌人为攻击者执行逃离。3/3敌人-144"}],"original":"ai/FOE-144-25-57-back.webp"},"153":{"behaviors":[[0,"closest",0,"藤蔓鞭击"],[1,"closest",0,"藤蔓捕获，藤蔓鞭击"],[3,"closest",0,"藤蔓捕获，藤蔓鞭击 +1{damage}"]],"abilities":[{"name":"藤蔓鞭击","die":"black","body":"发起4次攻击，每次2{damage}，尽可能均匀地分配给所有相邻流放者。若没有相邻流放者，则使用藤蔓捕获。"},{"name":"藤蔓捕获","body":"最近的流放者进行敏捷18检定。失败：将该流放者放置在与此敌人相邻的位置。"}],"weak":"+1{threat}","traits":["束缚：流放者试图离开相邻方格时，进行力量15检定。失败：不能离开，失去所有剩余移动。"],"reward":"6{xp}；特殊：长型-40。","id":"153","name":"藤蔓啮齿兽","faq":[{"question":"“藤蔓鞭击”的四次攻击是否每次都要投掷灰色命中骰?","answer":"是的！每次攻击都需掷一次命中骰。"},{"question":"“藤蔓鞭击+1{damage}”是什么意思?","answer":"四次攻击中的每一次都+1{damage}。"},{"question":"若我未通过移动(如通过传送门)离开相邻方格，“束缚”效果会触发吗?","answer":"不会,只有通过使用！!图标的移动才触发。"},{"question":"若流放者的“藤蔓捕获”检定失败,但敌人身边没有未被占据的相邻方格了，会如何处理？","answer":"将被藤蔓捕获的流放者放置在尽可能近的位置。"},{"question":"“藤蔓鞭击”开始执行时无相邻流放者,全部攻击都会跳过并触发“藤蔓捕获”,对吗?","answer":"对(且被击昏的流放者不计入相邻流放者数量)。"},{"question":"若“藤蔓鞭击”在攻击过程中击昏了所有相邻流放者,剩余攻击会如何处理？","answer":"剩余攻击会作废,且此次不会触发“藤蔓捕获”。"}],"original":"ai/FOE-153-25-59-back.webp"},"155":{"behaviors":[[0,"furthest",8,"抓捕"],[1,"most",8,"利爪，抓捕"],[3,"alert",8,"吞食"]],"abilities":[{"name":"利爪","die":"blue","body":"5{damage}","grid":[".XX.","X..X","X..X",".XX."],"origin":[1.5,1.5]},{"name":"吞食","body":"移除一个相邻的惊叹号标记。"},{"name":"抓捕","die":"red","body":"4{damage}。然后朝远离最近惊叹号标记的方向逃离6，再将目标放在相邻的位置。","grid":[".XX","...","..."],"origin":[1.5,1.5],"choice":true}],"weak":"+2{threat}","traits":["飞行：将不可通行和困难边界视为普通边界，忽略陷阱。"],"reward":"战斗以胜利或失败结束时，抽取事件-130。","id":"155","name":"翠蓝奇枭","faq":[{"question":"“抓捕”效果如何正确结算？","answer":"选择一个流放者为目标并发起攻击后,翠蓝奇枭向远离最近的事件指示物方向移动6格，同时携带被抓捕的流放者;最终将被抓捕流放者放置在与翠蓝奇枭尽可能近的可通行方格(由玩家选择）。"},{"question":"“最近”图标表示什么？","answer":"该图标代表“目标选择距离最近的事件指示物”。"},{"question":"代表什么？","answer":"获得键钥-502。"},{"question":"此敌人是否同时属于首领和杂兵?","answer":"是的！当你抽出“首领”或“杂兵”威胁卡，此敌人都会激活。不过若你抽出“所有敌人”威胁卡，此敌人也仅激活一次。"}],"original":"ai/FOE-155-25-61-back.webp"},"158":{"behaviors":[[0,"most",7,"狂野冲锋"],[1,"most",8,"狂野冲锋 +1{damage}"],[3,"most",9,"狂野冲锋 +2{damage}"]],"abilities":[{"name":"狂野冲锋","die":"yellow","body":"忽略普通限制，尽可能多地穿过非野猪生物，但不能在任何生物所在方格结束移动。对每名被穿过的流放者造成3{damage}；若穿过拉森，对拉森造成{bonus_damage}。每回合对每个生物至多一次。"}],"weak":"+1{threat}","reward":"无。","id":"158","name":"狂暴野猪","faq":[{"question":"对于“狂野冲锋”，若敌人的移动力仅足够部分穿过我，而非完全穿过我，会发生什么？","answer":"那就无法“狂野冲锋”穿过你，会在与你相邻的位置就结束移动。"},{"question":"若敌人“狂野冲锋\"穿过所有流放者后仍有剩余移动力，会如何？","answer":"敌人会停止移动，结束此次狂野冲锋。"},{"question":"“狂野冲锋\"的×伤害会因高的激活而提 {threat}高吗？","answer":"不会。O 问：代表什么？获得键钥-502。"},{"question":"若战士在一次“狂野冲锋”结算过程中使用“守护”技能，会发生什么?","answer":"这种情况下战士受到两次狂野冲锋的伤害（守护目标本应受到的一次，外加战士自己被撞到的一次）。，游荡者，会发生什么？游荡者会受到伤害，且失去隐藏状态(只有当狂暴野猪穿过了游荡者所在方格时才会这样)。"}],"original":"ai/FOE-158-25-64-back.webp"},"160":{"behaviors":[[0,"closest",null,"冰矛，向出口逃离3"],[1,"closest",null,"冰矛，向出口逃离4"],[3,"closest",null,"冰矛，向出口逃离5"]],"abilities":[{"name":"冰矛","die":"black","body":"3{distance}，5{damage}","grid":[".X.",".X.",".X.",".X."],"origin":[1,3],"originKind":"area"}],"weak":"向出口逃离3。","traits":["滑溜换位：逃离时，拉森可花费2{move}，与一名相邻流放者交换位置。"],"reward":"被击败时立即抽取事件-137。","id":"160","name":"流放者，拉森","faq":[{"question":"拉森“灵活换位”提及的2点移动力，是从他的逃离移动力点数中扣除?","answer":"是的。"},{"question":"若拉森试图与警戒指示物换位，会发生什么?","answer":"在“灵活换位”实际触发前，警戒指示物会被移除，拉森可正常移动。"},{"question":"“冰矛”效果如何生效？","answer":"拉森使用“冰矛”前不会移动，目标选择距离最近的流放者(且尽可能攻击到最多目标)。他会在3{distance}内选择一个方格作为“冰矛”位置网格的来源方格，按照范围能力的规则和位置网格图示来攻击流放者。"},{"question":"代表什么？","answer":"获得键钥-502。"},{"question":"对于技能/效果而言，拉森算“流放者”吗?","answer":"不算，他仍属于敌人。"},{"question":"此敌人是否同时属于首领和杂兵?","answer":"是的！当你抽出“首领”或“杂兵”威胁卡，此敌人都会激活。不过若你抽出“所有敌人”威胁卡，此敌人也仅激活一次。3/3敌人-160"}],"original":"ai/FOE-160-25-67-back.webp"},"163":{"behaviors":[[0,"most_hp",2,"撕咬"],[1,"most_hp",5,"撕咬"],[3,"furthest",6,"撕咬，撕咬"]],"abilities":[{"name":"撕咬","die":"yellow","body":"6{damage}，然后结算剧痛。","grid":[".X.",".@.","..."]},{"name":"剧痛","body":"若撕咬未被完全格挡，进行智力25检定。当前生命每比最大生命少1，检定结果+1。成功：该流放者获得键钥-34。失败：无事发生。"}],"weak":"+1{threat}","reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"163","name":"惑心之鼠","faq":[{"question":"“剧痛”效果如何正确结算?","answer":"若流放者因“撕咬”失去了{hp}，进行智力检定（即使当前{hp}为0）。本次检定获得当前{hp}与上限差值的加成(例如：你的{hp}上限为12，“撕咬”后剩余0{hp}，则获得12点加成)。注意只有通过此智力检定的流放者获得该键钥卡。"},{"question":"若有多名流放者获得键钥-34，应如何处理?","answer":"在这几名流放者之间共享键钥-34 4即可。"},{"question":"代表什么？","answer":"获得键钥-502。5/5敌人-163"}],"original":"ai/FOE-163-24-2-back.webp"},"164":{"behaviors":[[0,"most_hp",8,"践踏，逃离3"],[1,"most",9,"践踏 +1{damage}，逃离3"],[3,"none",null,"结算威胁0行为两次"]],"abilities":[{"name":"践踏","die":"black","body":"5{damage}，然后结算燃蹄。","grid":["XXX","X.X","..."],"origin":[1,1.5]},{"name":"燃蹄","body":"在此敌人占据的2×1矩形的四个角落放置火焰陷阱，用磨损指示物表示。当流放者与火焰陷阱共享一个方格时，立即移除陷阱，该流放者-2{hp}。","grid":["...","...","...","..."],"origin":[1,1.5],"markers":[[1,1],[2,1],[1,3],[2,3]]}],"weak":"燃蹄。若当前是流放者的回合，还要逃离3。","reward":"6{xp}；特殊：事件-142。","id":"164","name":"梦魔野猪","faq":[{"question":"哪些方格会触发一个火焰陷阱？","answer":"拥有火焰陷阱所在格角的四个方格均可触发。"},{"question":"若流放者移动穿过有火焰陷阱的方格(不是结束移动)，仍会受影响吗？","answer":"会。一旦流放者处于有火焰陷阱的方格内(包括火焰陷阱刚被放置时)，就需移除相应火焰陷阱并失去{hp}。若多名流放者同时与火焰陷阱相邻(如火焰陷阱刚被放置时)，由玩家选择受影响的流放者。"},{"question":"被击昏的流放者会触发火焰陷阱吗?","answer":"不会，火焰陷阱忽略被击昏的流放者。但一旦被击昏流放者获得{hp}，相应位置的火焰陷阱会立即对其生效。"},{"question":"一个格角上可放置多个火焰陷阱吗?","answer":"不能，每个格角最多一个火焰陷阱。但一个方格的四个格角是可各放置一个火焰陷阱的。"},{"question":"此敌人是否同时属于首领和杂兵?","answer":"是的！当你抽出“首领”或“杂兵”威胁卡，此敌人都会激活。不过若你抽出“所有敌人”威胁卡，此敌人也仅激活一次。"},{"question":"如果“践踏”没有可攻击的目标，“燃蹄”还会触发吗?","answer":"会，依然会触发。2/2敌人-164"}],"original":"ai/FOE-164-24-4-back.webp"},"167":{"behaviors":[[0,"most_hp",6,"挥砍，投进深坑"],[2,"most",7,"挥砍，挥砍，投进深坑"]],"abilities":[{"name":"挥砍","die":"yellow","body":"3{damage}","grid":["XXX",".@.","..."]},{"name":"投进深坑","body":"将目标沿直线投掷2格，进入深坑。","grid":["XXX",".@.","..."],"choice":true}],"weak":"+2{threat}","traits":["叶盾：此敌人在战斗开始时，在每张命中网格卡上各放置3个标记，使用护甲方块表示。","跃动：可跨过深坑，但不能在深坑中结束移动；跨越时将不可通行边界视为普通边界。"],"reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"167","name":"发抖的蜥精","faq":[{"question":"两名发抖的蜥精的“叶片盾牌”是否需分别记录？","answer":"是的，所以每名发抖的蜥精都可忽略前3次即将受到的伤害。"},{"question":"附加伤害与“叶片盾牌”如何互动？","answer":"附加伤害会与基础的伤害一同被忽略，且不会额外消耗“叶片盾牌”的标记。"},{"question":"“投进深坑”中的“投掷”是否指流放者会穿过(飞越)所有路径中间的生物?","answer":"是的。"},{"question":"“投进深坑”中，若流放者位置距离深坑超过2格,没办法被投掷进深坑，会如何处理？","answer":"流放者会被投掷到桥上。"},{"question":"“投进深坑”中，若流放者位于桥上,会被投向哪个方向？","answer":"流放者可选择向东或向西,但最终仍会落入深坑！"}],"original":"ai/FOE-167-24-7-back.webp"},"168":{"behaviors":[[0,"furthest",4,"精准射击"],[2,"most",5,"精准射击 +1{damage}"]],"abilities":[{"name":"精准射击","die":"red","body":"选择至多2名流放者：2–5{distance}，3{damage}。对每个目标，忽略遮蔽边界及至多1个墙壁边界。","attackType":"ranged"}],"weak":"+2{threat}","traits":["隐匿：与墙壁相邻时，此敌人免疫来自非相邻流放者的伤害。"],"reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"168","name":"受冻的弓箭手","faq":[{"question":"“隐匿”效果会阻止它被选为目标吗？","answer":"不会。"},{"question":"地图边缘算“墙壁”吗?","answer":"算。"}],"original":"ai/FOE-168-24-10-back.webp"},"169":{"behaviors":[[0,"furthest",6,"挥斧，投进深坑"],[1,"closest",7,"挥斧，挥斧，投进深坑"],[3,"most",8,"挥斧，挥斧，挥斧，投进深坑"]],"abilities":[{"name":"挥斧","die":"blue","body":"4{damage}","grid":["XXX",".@.","..."]},{"name":"投进深坑","body":"将目标沿直线投掷2格，进入深坑。","grid":["XXX",".@.","..."],"choice":true}],"weak":"+2{threat}","traits":["跃动：可跨过深坑，但不能在深坑中结束移动；跨越时将不可通行边界视为普通边界。"],"reward":"3{xp}；特殊：事件-147。","id":"169","name":"打霜之厄基","faq":[{"question":"“投进深坑”中的“投掷”是否指流放者会穿过(飞越)所有路径中间的生物?","answer":"是的。"},{"question":"“投进深坑”中，若流放者位置距离深坑超过2格，没办法被投掷进深坑，会如何处理?","answer":"流放者会被投掷到桥上。"},{"question":"“投进深坑”中，若流放者位于桥上，会被投向哪个方向？","answer":"流放者可选择向东或向西,但最终仍会落入深坑！"},{"question":"代表什么？","answer":"获得 键钥-502。"}],"original":"ai/FOE-169-24-12-back.webp"},"170":{"behaviors":[[0,"most",0,"战吼"],[3,"most",0,"收割，战吼"]],"abilities":[{"name":"收割","die":"black","body":"8{damage}","grid":["XXX","X.X","X.X","XXX"],"origin":[1,1.5]},{"name":"战吼","body":"按顺位，结算所有其他敌人的威胁0行为。"}],"weak":"+1{threat}","traits":["斧挡：非相邻流放者以基本攻击攻击此敌人时，自动失手。"],"reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"170","name":"库拉格·疤脚","faq":[{"question":"“斧头格挡”是会导致所有远程攻击未命中吗？","answer":"不会！仅非相邻的远程基本攻击会未命中（如游侠的“狙击”不是基本攻击，仍可生效)。"},{"question":"“斧头格挡”会导致技能中包含的非相邻远程基本攻击未命中吗？","answer":"会，“斧头格挡”会导致所有非相邻远程基本攻击未命中，包括技能中的此类攻击。"},{"question":"“斧头格挡”不会阻止它被非攻击类技能选为目标，对吗?(如“嘲讽”)","answer":"正确，仅非相邻的基本攻击会未命中。"},{"question":"若我与库拉格相邻，但攻击其底座中与我不相邻的方格(如使用长矛或苦无），“斧头格挡”会让我未命中吗？","answer":"不会！“斧头格挡”判定为流放者是否与库拉格模型底座的任意方格相邻，而非仅与你攻击的方格相邻。"}],"original":"ai/FOE-170-24-14-back.webp"},"172":{"behaviors":[[0,"closest",5,"劈斩或溜3"],[1,"furthest",6,"劈斩或溜4"],[3,"most",7,"劈斩或溜5"]],"abilities":[{"name":"劈斩或溜X","body":"若此敌人有4个或更少伤口，使用劈斩。否则，最近的流放者进行魅力18检定：失败，使用劈斩；成功，离开，此敌人被击败。"},{"name":"劈斩","die":"blue","body":"X{damage}。若没有完全格挡，失去1{kae}。","grid":["XXX",".@.","..."]}],"weak":"+1{threat}","reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"172","name":"疤脚盗贼","faq":[{"question":"X代表什么？","answer":"X是“劈斩或溜”的数值，根据激活的 行为，数值可能为3、4或5。"},{"question":"若敌人因自身能力被击败,算正常击败吗?","answer":"算，等同于将敌人所有生命点击伤。"}],"original":"ai/FOE-172-24-17-back.webp"},"174":{"behaviors":[[0,"closest",5,"投射或遁2"],[1,"furthest",5,"投射或遁3"],[3,"most",5,"投射或遁4"]],"abilities":[{"name":"投射或遁X","body":"若此敌人有4个或更少伤口，使用投射。否则，最近的流放者进行魅力18检定：失败，使用投射；成功，离开，此敌人被击败。"},{"name":"投射","die":"red","body":"选择至多2名流放者：4{distance}，X{damage}。"}],"weak":"+1{threat}","reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"174","name":"疤脚投手","faq":[{"question":"X代表什么？","answer":"X是“投射或遁”的数值，根据激活的行为，数值可能为2、3或4。"},{"question":"若敌人因自身能力被击败，算正常击败吗?","answer":"算，等同于将敌人所有生命点击伤。"}],"original":"ai/FOE-174-24-20-back.webp"},"177":{"behaviors":[[0,"格里姆",4,"纵火，+2{threat}"],[2,"格里姆",4,"纵火，火焰风暴"]],"abilities":[{"name":"纵火","body":"在每个火焰图标处增加1个火焰计数，用磨损指示物表示。"},{"name":"火焰风暴","die":"red","body":"所有流放者受到4{damage}。","attackType":"area"}],"weak":"+2{threat}","traits":["快跑：此敌人激活时，格里姆逃离3。","疯狂火焰：流放者所有掷骰-X；X等于地图上的火焰计数。","虚幻火焰：此敌人结束移动时，所有相邻流放者-2{hp}；此敌人将困难和不可通行边界视为普通边界。","不灭：此敌人第一次被击败时，治疗所有伤口，并获得1个力量标记。"],"reward":"8{xp}。","id":"177","name":"不懈的雾狮狼","faq":[{"question":"任何流放者都能执行“灭火”次级行动吗?","answer":"是的！任何流放者(包括格里姆)都能执行大型-89上描述的“灭火”次级行动。"},{"question":"格里姆的3点 能抵御“灵火”吗?","answer":"不能，仅能抵御“火焰风暴”的伤害。"},{"question":"若敌人移动0格，仍会触发“灵火”吗?","answer":"会。"},{"question":"“快跑！”效果需在敌人移动前结算吗?","answer":"是的！雾狮狼一激活，格里姆就会逃离3，之后再结算雾狮狼的激活。"},{"question":"首次击败它时，会发生什么?","answer":"还是不触发相应的弱点效果，治疗所有损伤，不恢复任何护甲。"},{"question":"若我使敌人变位，会触发“灵火”吗?","answer":"不会，仅移动效果会触发“灵火”。"},{"question":"“狂乱火焰”能将掷骰结果降低至1以下吗?","answer":"不能，掷骰结果最低为1。"},{"question":"每个☆上最多可放置多少个火焰标记?","answer":"无数量限制！"}],"original":"ai/FOE-177-24-22-back.webp"},"178":{"behaviors":[[0,"closest",4,"闪电束"],[1,"furthest",5,"闪电束，电击"],[3,"most",5,"化电穿行"]],"abilities":[{"name":"闪电束","die":"red","body":"攻击从此敌人开始沿直线持续延伸，线上的每名流放者受到5{damage}。","grid":[".X.",".X.","...","..."],"extend":true,"origin":[1,2.5],"originKind":"area"},{"name":"电击","die":"black","body":"3{distance}内的每名流放者受到3{damage}。","attackType":"area"},{"name":"化电穿行","body":"先使用闪电束，然后将此敌人放在尽可能接近最远已被闪电束命中的流放者的未占用方格中，随后使用电击。"}],"weak":"电击，然后逃离2。","reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"178","name":"闪电蜥蜴","faq":[{"question":"墙壁格边会阻挡“闪电束”吗？","answer":"会。墙壁(也只有墙壁)格边会阻挡此攻击的效果范围。"},{"question":"“化电穿行”后放置闪电蜥蜴时，可穿过不可穿越格边或墙壁格边放置吗？","answer":"不可。必须将其放置在距“最远被命中流放者”尽可能近的未被占据方格，且需在地图上的可通行方格内。"},{"question":"“化电穿行”放置闪电蜥蜴时，可旋转蜥蜴模型吗？","answer":"可以。"},{"question":"代表什么？","answer":"获得键钥-502。"},{"question":"“化电穿行”的“目标选择最多流放者”图标是对其中哪个攻击而言？","answer":"第一次攻击，即闪电束。"}],"original":"ai/FOE-178-24-25-back.webp"},"179":{"behaviors":[[0,"furthest",3,"充能2"],[1,"most",4,"充能3"],[3,"most",5,"充能5"]],"abilities":[{"name":"充能X","body":"在此处放置X个风暴计数，使用护甲方块表示。"},{"name":"冲击波","die":"yellow","body":"4{distance}内的每名流放者受到伤害；{damage}等于风暴计数。"}],"weak":"充能2。","traits":["召唤风暴：每当从威胁牌组抽取一张卡，充能1。","放电：风暴使者行动后，若有至少5个风暴计数，使用冲击波，然后移除所有风暴计数。"],"reward":"6{xp}；特殊：事件-189。","id":"179","name":"风暴使者","faq":[{"question":"既然“充能”不直接发起攻击，那应如何确定目标与移动方式?","answer":"按“冲击波”的攻击距离与能力类型来确定（哪怕冲击波不一定会触发）。{distance} 问：“冲击波”计算⑩距离时使用哪种能力类型？使用范围能力（→）类型。"},{"question":"“释放”是在任意敌人回合结束时触发(如抽取威胁卡导致达到数量)，还是仅在风暴使者实际行动后触发?","answer":"仅在风暴使者实际行动(移动并充能)后,在其激活完成后立即触发。"},{"question":"此敌人是否同时属于首领和杂兵？","answer":"是的！当你抽出“首领”或“杂兵”威胁卡，此敌人都会激活。不过若你抽出“所有敌人”威胁卡，此敌人也仅激活一次。2/2敌人-179"}],"original":"ai/FOE-179-24-27-back.webp"},"185":{"behaviors":[[0,"furthest",5,"喷泉"],[1,"closest",5,"暗流1，喷泉"],[3,"most",6,"暗流2，喷泉 +1{damage}"]],"abilities":[{"name":"暗流X","body":"选择目标前，将每名流放者向此敌人拉近X格。"},{"name":"喷泉","die":"yellow","body":"4{distance}，4{damage}。若流放者在水域中，+2{damage}。"}],"weak":"若此敌人的两个弱点均已受伤，重生此敌人。","traits":["流体：将困难边界视为普通边界，可穿过流放者所在方格。","束缚：若被击败，若可能，立即在一个缚灵点相邻处重生。"],"reward":"3{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"185","name":"水元素","faq":[{"question":"“重生”应如何正确结算？","answer":"将敌人放置在你选择的缚灵球相邻的可通行方格上，移除所有损伤指示物并恢复所有护甲，移除流放者施加的效果(如标记)，若有强化指示物则保留。"},{"question":"若已无剩余缚灵球，且我击伤了水元素的两个弱点，会发生什么？","answer":"无事发生，因水元素无法重生。"},{"question":"若场上无缚灵球，被击败的水元素不会重生，对吗？","answer":"正确。"},{"question":"“暗流”效果结算时，水元素是在效果前还是效果后移动？","answer":"“暗流”在水元素移动前结算，因移动在目标选择后进行，而“暗流”在目标选择前结算。"},{"question":"“喷泉”中的=代表什么？","answer":"地图上带有水符号的方格。"}],"original":"ai/FOE-185-24-32-back.webp"},"187":{"behaviors":[[0,"none",0,"消融仪式2"],[1,"none",0,"消融仪式3"],[3,"none",0,"消融仪式4"]],"abilities":[{"name":"消融仪式X","body":"相邻流放者-X{hp}。在冰川轨道上放置X个护甲方块。"}],"weak":"+2{threat}","reward":"无。","id":"187","name":"法师，拉森","faq":[{"question":"“消融仪式”是否会向“冰川轨”添加护甲？","answer":"在这种情况下，护甲方块的用途为计数,用于记录累积的数量。"},{"question":"“消融仪式”会受强化指示物影响吗?","answer":"强化指示物会影响相邻流放者失去的{hp}数量，但不会影响添加到“冰川轨”的护甲方块数量。2/2敌人-187"}],"original":"ai/FOE-187-24-34-back.webp"},"188":{"behaviors":[[0,"closest",7,"沉溺，+1{threat}"],[1,"most",4,"涡流"],[3,"most",6,"涡流，沉溺"]],"abilities":[{"name":"涡流","die":"red","body":"将每名流放者向此敌人拉近2格。随后，3{distance}内的每名流放者受到3{damage}；若处于水域中，再+4{damage}。","attackType":"area"},{"name":"沉溺","body":"进行耐力20检定。成功：-1{sp}且-1{hp}；失败：-4{sp}且-4{hp}。水域中的流放者自动失败。","grid":[".XX.","X..X","X..X",".XX."],"origin":[1.5,1.5],"originKind":"area"}],"weak":"+2{threat}","traits":["流体：将困难边界视为普通边界，可穿过流放者所在方格。"],"reward":"无。","id":"188","name":"巨型水元素","faq":[{"question":"“沉溺”与“涡流”中的=代表什么?","answer":"该图标代表水中的方格，可参考地图查看具体包含哪些方格。"},{"question":"选择巨型水元素“涡流”效果的优先位置时，该效果视为距离2还是4的攻击?","answer":"视为距离4的攻击，因“拉近2格(对所有人)”+“距离2格的攻击(针对拉近后)”=总距离4。"},{"question":"“涡流\"效果与游荡者的警戒指示物如何互动？","answer":"警戒指示物会被拉近2格，然后被移除，且游荡者失去隐藏状态。"},{"question":"“沉溺”效果与游荡者的警戒指示物如何互动？","answer":"该指示物不受此能力影响。"},{"question":"此敌人是否同时属于首领和杂兵?","answer":"是的！当你抽出“首领\"或“杂兵\"威胁卡，此敌人都会激活。不过若你抽出“所有敌人”威胁卡，此敌人也仅激活一次。"}],"original":"ai/FOE-188-24-36-back.webp"},"189":{"behaviors":[[0,"none",null,"无"]],"abilities":[],"traits":["障碍物：不会离开所在方格。","加速剂：若巨浪进入此敌人所在方格，+1{threat}，随后移除此敌人。","减速剂：若此敌人被击败，-1{threat}。"],"reward":"无。","id":"189","name":"水元素之手","faq":[{"question":"水元素之手能否通过任何方式移动?","answer":"不能。无法通过任何方式(变位、推远、拉近等)将其移至其他方格。"},{"question":"水元素之手视为普通敌人吗?我能否移动穿过水元素之手？","answer":"水元素之手属于普通敌人，因此你无法移动穿过水元素之手，且水元素之手占据其所在方格。"}],"original":"ai/FOE-189-24-38-back.webp"},"190":{"behaviors":[[0,"furthest",0,"激波，+3{threat}"],[1,"most_hp",0,"激波，弄潮"],[3,"most",0,"弄潮，浪涌，浪涌"]],"abilities":[{"name":"弄潮","die":"blue","body":"水域方格上的流放者受到4{damage}。其他每名流放者移到最近的未占用水域方格。","attackType":"area"},{"name":"激波","die":"black","body":"8{distance}，4{damage}。","attackType":"ranged"},{"name":"浪涌","body":"立即将巨浪推进1行。"}],"weak":"+2{threat}","traits":["巨浪绑定：任何效果都不能使此敌人离开巨浪；将困难边界视为普通边界。"],"reward":"10{xp}；特殊：中型-77。","id":"190","name":"水元素，拉森","faq":[{"question":"“弄潮”中的=代表什么？","answer":"该图标代表水中的方格(无论是否为白色背景)，可参考地图查看具体包含哪些方格。"},{"question":"针对“巨浪绑定”效果，我能否使用推远敌人的技能？","answer":"可以，只要技能不会将其移至巨浪范围外即可。"}],"original":"ai/FOE-190-24-40-back.webp"},"191":{"behaviors":[[0,"宝珠",4,"剑刺"]],"abilities":[{"name":"剑刺","die":"black","body":"5{damage}","grid":[".X.",".@.","..."]}],"weak":"+1{threat}","traits":["亡灵：免疫中毒。治疗效果可将此敌人视为流放者来选择目标；每治疗1{hp}，对其造成{bonus_damage}。","强化：被宝珠持有者摧毁时，生成2次充能。"],"reward":"无。","id":"191","name":"沼泽战士","faq":[{"question":"若此敌人通过“亡灵”能力要受到多点☆}，是所有伤害一起结算？","answer":"是的，同一次治疗就像是同一次攻击那样。所以相应地，若你在一次治疗中击败此敌人,弱点效果不触发；此外，你还能将多点此瞄准伤害分配至同一点，如用2点击伤一个护甲点。"},{"question":"若此敌人受牧师“光芒普照”技能影响，是否会同时受到普通伤害与治疗带来的额外伤害？","answer":"是的！而且普通伤害与治疗带来的伤害会一起适用。"},{"question":"若处于隐藏状态的游荡者是“宝珠持有者”，仍会被选为目标吗？","answer":"是的。敌人会忽略警戒指示物并知晓游荡者的真实位置，宝珠在呼唤他们！"}],"original":"ai/FOE-191-24-42-back.webp"},"192":{"behaviors":[[0,"宝珠",4,"锥头箭"]],"abilities":[{"name":"锥头箭","die":"red","body":"2–4{distance}，3{damage}。","attackType":"ranged"}],"weak":"+1{threat}","traits":["亡灵：免疫中毒。治疗效果可将此敌人视为流放者来选择目标；每治疗1{hp}，对其造成{bonus_damage}。"],"reward":"无。","id":"192","name":"沼泽弓箭手","faq":[{"question":"若此敌人通过“亡灵”能力要受到多点☆},是所有伤害一起结算？","answer":"是的，同一次治疗就像是同一次攻击那样。所以相应地，若你在一次治疗中击败此敌人，弱点效果不触发；此外，你还能将多点此瞄准伤害分配至同一点，如用2点击伤一个护甲点。"},{"question":"若此敌人受牧师“光芒普照”技能影响,是否会同时受到普通伤害与治疗带来的额外伤害？","answer":"是的！而且普通伤害与治疗带来的伤害会一起适用。"},{"question":"若处于隐藏状态的游荡者是“宝珠持有者”，仍会被选为目标吗？","answer":"是的。敌人会忽略警戒指示物并知晓游荡者的真实位置，宝珠在呼唤他们！"}],"original":"ai/FOE-192-24-45-back.webp"},"193":{"behaviors":[[0,"宝珠",4,"切斩"]],"abilities":[{"name":"切斩","die":"blue","body":"3{damage}","grid":[".X.",".@.","..."]}],"weak":"+1{threat}","traits":["亡灵：免疫中毒。治疗效果可将此敌人视为流放者来选择目标；每治疗1{hp}，对其造成{bonus_damage}。"],"reward":"无。","id":"193","name":"沼泽骷髅","faq":[{"question":"若此敌人通过“亡灵”能力要受到多点{☆，是所有伤害一起结算？","answer":"是的，同一次治疗就像是同一次攻击那样。所以相应地，若你在一次治疗中击败此敌人，弱点效果不触发；此外，你还能将多点此瞄准伤害分配至同一点，如用2点 击伤一个护甲点。"},{"question":"若此敌人受牧师“光芒普照”技能影响,是否会同时受到普通伤害与治疗带来的额外伤害？","answer":"是的！而且普通伤害与治疗带来的伤害会一起适用。"},{"question":"若处于隐藏状态的游荡者是“宝珠持有者”，仍会被选为目标吗？","answer":"是的。敌人会忽略警戒指示物并知晓游荡者的真实位置，宝珠在呼唤他们！"}],"original":"ai/FOE-193-24-48-back.webp"},"194":{"behaviors":[[0,"宝珠",0,"搜寻，葬火"],[2,"宝珠",0,"搜寻，葬火，恐惧"]],"abilities":[{"name":"葬火","die":"blue","body":"若宝珠持有者位于一只骷髅的2{distance}内，摧毁该骷髅，并对其2{distance}内的所有流放者造成9{damage}。否则，使用搜寻。","attackType":"area"},{"name":"搜寻","body":"在K处重生所有被摧毁的杂兵。若没有敌人重生，则改为所有杂兵向宝珠持有者移动4格。"},{"name":"恐惧","body":"宝珠持有者进行感知18检定。失败：朝远离传说裹纱鬼的方向逃离6。"}],"weak":"恐惧。","traits":["灵体：免疫伤害。","传说裹纱鬼被击败时，立即抽取事件-204。"],"reward":"见本卡击败时的指示。","id":"194","name":"传说裹纱鬼","faq":[{"question":"“葬火”效果中，计算骷髅与目标的距离时使用哪种能力类型？","answer":"使用范围能力（）类型。"},{"question":"若宝珠持有者2{distance}内有多个骷髅，会发生什么?","answer":"由玩家选择其中一个骷髅作为“葬火”的来源，且仅该骷髅会被摧毁来形成葬火。"},{"question":"若处于隐藏状态的游荡者是宝珠持有者，“葬火”效果会如何处理？","answer":"“葬火”仅关注宝珠持有者的实际位置，隐藏状态无法保护该游荡者。"},{"question":"对于涉及攻击来源的技能而言，“葬火”的攻击来源是传说裹纱鬼还是骷髅?","answer":"来源是骷髅。"},{"question":"“葬火”效果中的“骷髅”具体是指什么?","answer":"就是敌人-191、敌人-192和故人-1932/2敌人-194"}],"original":"ai/FOE-194-24-50-back.webp"},"197":{"behaviors":[[0,"furthest",4,"水爆"],[2,"most",6,"水爆，潜水"]],"abilities":[{"name":"潜水","body":"移到最近的水域方格，然后治疗6个生命点。"},{"name":"水爆","die":"black","body":"3{distance}内的每名流放者受到4{damage}；若处于水域中，改为7{damage}。若完全格挡，该流放者向最近水域平移1格。","attackType":"melee"}],"weak":"+2{threat}","traits":["流体：将困难边界视为普通边界，可穿过流放者所在方格。"],"reward":"6{xp}；战利品：2–9：1{kae}；10–19：2{kae}；20：1件铁制物品。","id":"197","name":"水灵守卫","faq":[{"question":"三代表什么？","answer":"该图标代表水中的方格，可参考地图查看具体包含哪些方格。"},{"question":"若我已位于三，且未完全阻挡“水爆”，会变位至其他位置吗?","answer":"不会。"}],"original":"ai/FOE-197-24-53-back.webp"},"198":{"behaviors":[[0,"closest",0,"吞噬"],[2,"closest",0,"吞噬，激流"]],"abilities":[{"name":"吞噬","die":"blue","body":"若此敌人体内已有流放者，该流放者受到12{damage}。否则，将最近的流放者放入此敌人体内，可将模型放在远古水灵守卫模型上表示。","attackType":"melee"},{"name":"激流","body":"水域中的每名流放者进行耐力25检定。失败：-3{sp}且-3{hp}。然后，将每名不在水域中的流放者放在最近的水域方格。"}],"weak":"治疗2个生命点。","traits":["排出：此敌人一次受到至少4个伤口时，从其正上方1英寸处落下一枚护甲方块，将被吞噬的流放者放在最靠近方块落点的水域方格，然后移除该方块。"],"reward":"6{xp}，以及键钥-143。","id":"198","name":"远古水灵守卫","faq":[{"question":"“排出”效果中的“一次性”是什么意思？","answer":"4个损伤指示物必须通过一次行动或延迟效果（如陷阱)造成(包括相关附加伤害）；提醒一下，损伤与伤害是不同概念，损伤是指实际放到网格卡上的损伤指示物。"},{"question":"若被吞噬的流放者被击昏，会发生什么?","answer":"立即将其排出。"},{"question":"被吞噬的流放者如何结算“激流”效果？","answer":"因为你必然也处于大量水附近，因此也要进行耐力检定，检定结果本身不会影响被吞噬状态(除非被击昏了）。"},{"question":"被吞噬期间，我能否与远古水灵守卫外部的事物建立视线/效果线?（如法师能否用“闪烁”逃脱？)","answer":"不能。你无法选择远古水灵守卫外部的任何事物为目标，包括方格和格角。"},{"question":"将我的模型放入远古水灵守卫内部时，是否需要注意摆放方式？","answer":"是的!请注意稍微调整角度来顺利放入你的流放者模型（尤其是法师模型）。"}],"original":"ai/FOE-198-24-55-back.webp"},"200":{"behaviors":[[0,"furthest","∞","致命飞扑"],[2,"most","∞","裂爪，裂爪"]],"abilities":[{"name":"致命飞扑","die":"red","body":"沿最短路线飞向目标。造成5{damage}，每飞过1格再+1{damage}。","attackType":"melee"},{"name":"裂爪","die":"black","body":"3{distance}内的每名流放者受到5{damage}。","attackType":"melee"}],"weak":"+2{threat}","traits":["酸血：流放者将受到治疗时，掷一个d20。若结果不大于此敌人的伤口数，治疗量减少5{hp}，最少为0。"],"reward":"1{xp}；特殊：事件-223。","id":"200","name":"夜魔","faq":[{"question":"移动中的“∞”代表什么？","answer":"无限移动。夜魔可移动任意数量的方格以到达目标位置(但会选择最短路径)。"},{"question":"“致命飞扑”中的“飞行”具体指什么？","answer":"会受墙壁阻挡，可移动穿过流放者(但不可在流放者方格结束移动）。"},{"question":"“致命飞扑”与陷阱如何互动?","answer":"此敌人移动时会飞越陷阱，忽略陷阱效果；到达目标相邻位置后，会落地攻击，她会先触发所有与她相邻的陷阱，再结算“致命飞扑”的伤害(若陷阱将其击败，则伤害不用结算）。"},{"question":"若因格子空间不足导致最远的流放者无法被“致命飞扑”选为目标，会如何处理？","answer":"此敌人会选择“结束移动后可实际攻击到的最远流放者”为目标。"},{"question":"“酸血”效果的20面骰掷骰结果能否通过某种方式被修正？","answer":"不能。该投掷由游戏机制触发，而非玩家操作，因此无法被修正。"},{"question":"若多名目标同时受到治疗，“酸血”效果是为每个目标单独掷骰，还是仅掷一次?","answer":"仅掷一次，所有目标的治疗量均减少5点{hp}。2/2敌人-200"}],"original":"ai/FOE-200-24-57-back.webp"},"201":{"behaviors":[[0,"most","∞","殊死突袭"],[7,"most","∞","殊死突袭 +5{damage}"]],"abilities":[{"name":"殊死突袭","die":"black","body":"从最近的流放者开始，依次飞到每名流放者的相邻方格，对各人造成5{damage}。","attackType":"melee"}],"weak":"+2{threat}","traits":["翻飞腾挪：在流放者回合中免疫伤害，除非攻击掷骰的自然点数至少为17。不掷d20的能力在流放者回合中不能对其造成伤害；附加伤害正常生效。","酸血：流放者将受到治疗时，掷一个d20。若结果不大于此敌人的伤口数，治疗量减少5{hp}，最少为0。"],"reward":"10{xp}，以及事件-224。","id":"201","name":"狂暴夜魔","faq":[{"question":"“殊死突袭”中的“飞行”具体指什么？","answer":"会受墙壁阻挡,可移动穿过流放者(但不可在流放者方格结束移动）。"},{"question":"“殊死突袭”与处于隐藏状态的游荡者如何互动？","answer":"殊死突袭过程中,在攻击警戒指示物后,夜魔会发现此时失去隐藏状态的游荡者，并在本次殊死突袭中攻击该游荡者。"},{"question":"“殊死突袭”与陷阱如何互动?","answer":"此敌人移动时会飞越陷阱,忽略陷阱效果；到达每个目标相邻位置后，会落地攻击，她会先触发所有与她相邻的陷阱，再结算“殊死突袭”的伤害（若陷阱将其击败，则伤害不用结算）。"},{"question":"“翻飞腾挪”效果与多段攻击技能如何互动？","answer":"只有相关掷骰骰面大于等于17的攻击轨迹才能正常造成伤害；附加伤害正常生效，别忘了参考事件-374！"}],"original":"ai/FOE-201-24-59-back.webp"},"CE":{"behaviors":[],"abilities":[],"traits":["这是命中网格的战斗示例卡，没有独立的AI行动面。请按对应战斗示例的说明使用。"],"reward":"此示例卡不列战利品。","id":"CE","name":"练习假人","faq":[]}};
